import { createRequire } from 'node:module'
const runtime = process.env.HOME + '/.local/share/omgithub-playwright'
const require = createRequire(runtime + '/package.json')
const { chromium } = require('playwright')
const config = JSON.parse(require('node:fs').readFileSync(runtime + '/linux.json', 'utf8'))
process.env.DISPLAY ||= require('node:fs').readFileSync(runtime + '/display', 'utf8').trim()

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 390, height: 844 } })
page.setDefaultTimeout(20000)
const errors = []
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message + '\n' + (e.stack || '')))
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()) })
page.on('response', r => { if (r.status() >= 400) errors.push('HTTP ' + r.status() + ': ' + r.url()) })

await page.goto('http://127.0.0.1:4113/', { waitUntil: 'load' })
await page.waitForTimeout(800)

// New Adventure -> creation screen
await page.click('#btnNewGame')
await page.waitForTimeout(500)
const creationVisible = await page.locator('#creationScreen').isVisible().catch(() => false)
console.log('creation screen visible:', creationVisible)
await page.screenshot({ path: '/tmp/opencode/caps/creation.png' })

// Enter Aetheria
await page.click('#btnCreate')
await page.waitForFunction(() => !document.getElementById('loadingScreen').classList.contains('hidden') ||
  !document.getElementById('hud').classList.contains('hidden'), null, { timeout: 15000 }).catch(() => errors.push('NEITHER: neither loading nor hud appeared'))
await page.waitForTimeout(3000)
const hudVisible = await page.locator('#hud').isVisible().catch(() => false)
console.log('hud visible:', hudVisible)
await page.waitForTimeout(6000)
await page.screenshot({ path: '/tmp/opencode/caps/ingame.png' })

// poke a few modals
for (const sel of ['[data-ui="openBag"]', '[data-ui="openCharacter"]', '[data-ui="openMap"]', '[data-ui="openShop"]']) {
  await page.locator(sel).click({ timeout: 3000 }).catch(e => errors.push('CLICKFAIL ' + sel))
  await page.waitForTimeout(700)
  await page.keyboard.press('Escape').catch(() => {})
  const backdrop = page.locator('.modal-backdrop')
  if (await backdrop.isVisible().catch(() => false)) await page.click('.modal-backdrop').catch(() => {})
  await page.waitForTimeout(400)
}
await page.screenshot({ path: '/tmp/opencode/caps/after-modals.png' })

// run the game loop a bit more so combat/render errors surface
await page.waitForTimeout(8000)
await page.screenshot({ path: '/tmp/opencode/caps/incombat.png' })

// reload to test save/load path
await page.reload({ waitUntil: 'load' })
await page.waitForTimeout(1000)
const contVisible = await page.locator('#btnContinue').isVisible().catch(() => false)
console.log('continue button visible after reload:', contVisible)
if (contVisible) {
  await page.click('#btnContinue')
  await page.waitForTimeout(4000)
  console.log('hud after continue:', await page.locator('#hud').isVisible().catch(() => false))
  await page.screenshot({ path: '/tmp/opencode/caps/continued.png' })
}

console.log('--- ERRORS (' + errors.length + ') ---')
for (const e of errors.slice(0, 40)) console.log(e)
await browser.close()

