231:       this.data.character.petsOwned = this.data.character.petsOwned || [];
232:       this.data.character.costumesOwned = this.data.character.costumesOwned || [];
233:       this.data.shop = this.data.shop || { owned: [], purchases: [] };
234:       this._statsDirty = true;
235:       const st = this.stats();
236:       this.data.character.hp = clamp(this.data.character.hp || st.maxHp, 1, st.maxHp);
237:       this.data.character.mana = clamp(this.data.character.mana || st.maxMana, 0, st.maxMana);
