250:   // ------------------------------------------------------------
251:   // core character helpers
252:   // ------------------------------------------------------------
253:   get char() { return this.data?.character; }
254:   get cls() { return CLASSES[this.char?.classId] || CLASSES.warrior; }
255:   get faction() { return FACTIONS[this.char?.faction] || FACTIONS.angel; }
