262:   xpToNext(level = this.char.level) {
263:     return CONFIG.combat.xpCurve(level);
264:   }
265: 
266:   stats() {
267:     if (!this.data) return null;
268:     if (!this._statsDirty && this._statsCache) return this._statsCache;
269:     const c = this.char;
270:     const base = this.cls.base;
271:     const growth = this.cls.growth;
272:     const lv = c.level;
273:     const stats = {
274:       str: base.str + growth.str * (lv - 1),
275:       int: base.int + growth.int * (lv - 1),
276:       dex: base.dex + growth.dex * (lv - 1),
277:       vit: base.vit + growth.vit * (lv - 1),
278:       crit: CONFIG.combat.baseCrit,
279:       atk: 0, def: 0, critBonus: 0
280:     };
281:     for (const slot of SLOTS) {
282:       const item = this.data.equipped[slot.id];
283:       if (!item) continue;
284:       for (const key of ['str', 'int', 'dex', 'vit', 'atk', 'def']) {
285:         stats[key] += item.stats?.[key] || 0;
286:       }
287:       if (item.stats?.crit) stats.critBonus += item.stats.crit;
288:       for (const b of item.bonuses || []) {
289:         if (b.stat === 'crit') stats.critBonus += b.value / 100;
290:         else if (stats[b.stat] !== undefined) stats[b.stat] += b.value;
291:       }
292:     }
293:     const primary = stats[this.cls.primary] || 0;
294:     stats.primary = primary;
295:     stats.maxHp = Math.floor(70 + stats.vit * 15 + lv * 12);
296:     stats.maxMana = Math.floor(30 + stats.int * 11 + lv * 5);
297:     stats.attack = Math.floor(8 + stats.atk * 1.25 + primary * 2.35 + lv * 1.6);
298:     stats.defense = Math.floor(stats.def * 1.7 + stats.vit * 0.3);
299:     stats.damageReduction = stats.defense / (stats.defense + 160);
300:     stats.crit = clamp(stats.crit + stats.critBonus, 0, CONFIG.combat.critCap);
301:     stats.critDamage = 1.75;
302:     const weapon = this.data.equipped.weapon;
303:     const weaponSpeed = ITEM_BASE[c.classId]?.weapon?.speed || 2.0;
304:     const tierSpeed = weapon ? ({ 1: 0.95, 2: 0.9, 3: 0.86 }[weapon.tier] || 0.9) : 1;
305:     let attackInterval = weaponSpeed * tierSpeed;
306:     const asBuff = this.activeBuff('attackSpeed');
307:     if (asBuff) attackInterval /= asBuff.mult;
308:     stats.attackInterval = attackInterval;
309:     stats.attackSpeedPct = 1 / attackInterval;
310:     stats.attackRange = c.classId === 'archer' ? 3.4 : c.classId === 'mage' ? 2.9 : 1.65;
311:     let move = 3.1;
312:     if (c.mountActive) {
313:       const mount = SHOP.mounts.find(m => m.id === c.mountActive);
314:       if (mount) move *= mount.speed;
315:     }
316:     const msBuff = this.activeBuff('moveSpeed');
317:     if (msBuff) move *= msBuff.mult;
318:     stats.moveSpeed = move;
319:     stats.power = Math.floor(stats.attack * (1 + stats.crit * (stats.critDamage - 1)) * 1.2 + stats.maxHp * 0.08 + stats.defense * 0.5);
320:     this._statsCache = stats;
321:     this._statsDirty = false;
322:     return stats;
323:   }
324: 
325:   recalcHP() {
326:     const st = this.stats();
327:     this.char.hp = clamp(this.char.hp, 1, st.maxHp);
328:     this.char.mana = clamp(this.char.mana, 0, st.maxMana);
329:   }
