338:   restoreMana(amount) {
339:     const st = this.stats();
340:     this.char.mana = clamp(this.char.mana + amount, 0, st.maxMana);
341:     Events.emit('mana', this.char.mana);
342:   }
343: 
344:   damagePlayer(amount) {
345:     const st = this.stats();
346:     const reduced = Math.max(1, Math.round(amount * (1 - st.damageReduction)));
347:     this.char.hp = Math.max(0, this.char.hp - reduced);
348:     Events.emit('hp', this.char.hp);
349:     return reduced;
350:   }
351: 
352:   gainXp(amount, category = 'combat') {
353:     if (amount <= 0) return;
354:     if (this.char.premium.xpUntil > Date.now()) amount = Math.round(amount * 1.5);
355:     this.char.xp += amount;
356:     let levels = 0;
357:     while (this.char.level < 60 && this.char.xp >= this.xpToNext()) {
358:       this.char.xp -= this.xpToNext();
359:       this.char.level++;
360:       levels++;
361:       this._invalidate();
362:       const st = this.stats();
363:       this.char.hp = st.maxHp;
364:       this.char.mana = st.maxMana;
365:       Events.emit('levelup', this.char.level);
366:     }
367:     if (this.char.level >= 60) this.char.xp = Math.min(this.char.xp, this.xpToNext(60));
368:     Events.emit('xp', { xp: this.char.xp, level: this.char.level, levels });
369:     Events.emit('character', this.char);
370:     return levels;
371:   }
