373:   activeBuff(type) {
374:     const now = Date.now();
375:     return (this.char.buffs || []).find(b => b.type === type && b.until > now);
376:   }
377: 
378:   activeBuffs() {
379:     const now = Date.now();
380:     return (this.char.buffs || []).filter(b => b.until > now);
381:   }
382: 
383:   clearExpiredBuffs() {
384:     const before = (this.char.buffs || []).length;
385:     this.char.buffs = (this.char.buffs || []).filter(b => b.until > Date.now());
386:     if (before !== this.char.buffs.length) this._invalidate();
387:   }
