389:   addBuff(def) {
390:     const existing = this.char.buffs.find(b => b.id === def.id);
391:     if (existing) {
392:       existing.until = Date.now() + def.seconds * 1000;
393:     } else {
394:       this.char.buffs.push({ id: def.id, type: def.buff, mult: def.mult, name: def.name, until: Date.now() + def.seconds * 1000 });
395:     }
396:     this._invalidate();
397:   }
