399:   usePotion(id) {
400:     const def = CONFIG.potions[id];
401:     if (!def) return { ok: false, msg: 'Unknown potion.' };
402:     const count = this.char.consumables[id] || 0;
403:     if (count <= 0) return { ok: false, msg: 'You have none of those.' };
404:     if (def.heal) {
405:       const st = this.stats();
406:       if (this.char.hp >= st.maxHp) return { ok: false, msg: 'Health is already full.' };
407:       this.char.consumables[id] = count - 1;
408:       this.heal(def.heal);
409:       return { ok: true, msg: `Restored ${def.heal} health.` };
410:     }
411:     if (def.mana) {
412:       const st = this.stats();
413:       if (this.char.mana >= st.maxMana) return { ok: false, msg: 'Mana is already full.' };
414:       this.char.consumables[id] = count - 1;
415:       this.restoreMana(def.mana);
416:       return { ok: true, msg: `Restored ${def.mana} mana.` };
417:     }
418:     if (def.buff) {
419:       this.char.consumables[id] = count - 1;
420:       this.addBuff({ ...def, id });
421:       return { ok: true, msg: `${def.name} active for ${Math.round(def.seconds / 60)} minutes.` };
422:     }
423:     return { ok: false, msg: 'Nothing happens.' };
424:   }
