426:   buyPotion(id, packages = 1) {
427:     const def = CONFIG.potions[id];
428:     if (!def) return { ok: false, msg: 'Unknown potion.' };
429:     const total = def.price * packages;
430:     if (!this.spendGold(total, 'potion_purchase', `${def.name} ×${CONFIG.potionPackageSize * packages}`)) {
431:       return { ok: false, msg: 'Not enough gold.' };
432:     }
433:     const amount = CONFIG.potionPackageSize * packages;
434:     this.char.consumables[id] = (this.char.consumables[id] || 0) + amount;
435:     Events.emit('inventory', this.data.inventory);
436:     return { ok: true, msg: `Purchased ${amount} × ${def.name}.` };
437:   }
