439:   // ------------------------------------------------------------
440:   // economy ledger
441:   // ------------------------------------------------------------
442:   addGold(amount, category = 'misc', note = '') {
443:     amount = Math.max(0, Math.round(amount));
444:     if (!amount) return 0;
445:     if (category === 'monster' && this.char.premium.goldUntil > Date.now()) amount = Math.round(amount * 1.25);
446:     this.char.gold += amount;
447:     const eco = this.data.economy;
448:     eco.sources[category] = (eco.sources[category] || 0) + amount;
449:     eco.lifetimeEarned += amount;
450:     eco.sessionEarned += amount;
451:     eco.history.unshift({ ts: Date.now(), type: 'in', amount, category, note });
452:     eco.history = eco.history.slice(0, 120);
453:     Events.emit('gold', this.char.gold);
454:     Events.emit('economy', eco);
455:     return amount;
456:   }
457: 
458:   spendGold(amount, category = 'misc', note = '') {
459:     amount = Math.max(0, Math.round(amount));
460:     if (amount <= 0) return true;
461:     if (this.char.gold < amount) return false;
462:     this.char.gold -= amount;
463:     const eco = this.data.economy;
464:     eco.sinks[category] = (eco.sinks[category] || 0) + amount;
465:     eco.lifetimeSpent += amount;
466:     eco.history.unshift({ ts: Date.now(), type: 'out', amount, category, note });
467:     eco.history = eco.history.slice(0, 120);
468:     Events.emit('gold', this.char.gold);
469:     Events.emit('economy', eco);
470:     return true;
471:   }
