473:   addGems(amount) {
474:     this.char.gems += amount;
475:     Events.emit('gems', this.char.gems);
476:   }
477: 
478:   spendGems(amount) {
479:     if (this.char.gems < amount) return false;
480:     this.char.gems -= amount;
481:     Events.emit('gems', this.char.gems);
482:     return true;
483:   }
