485:   economySummary() {
486:     const eco = this.data.economy;
487:     const hours = Math.max(0.01, this.data.playtime / 3600);
488:     const goldPerHour = eco.lifetimeEarned / hours;
489:     const totalIn = Object.values(eco.sources).reduce((a, b) => a + b, 0);
490:     const totalOut = Object.values(eco.sinks).reduce((a, b) => a + b, 0);
491:     return {
492:       totalIn, totalOut, net: totalIn - totalOut,
493:       sources: eco.sources, sinks: eco.sinks,
494:       lifetimeEarned: eco.lifetimeEarned, lifetimeSpent: eco.lifetimeSpent,
495:       goldPerHour, hours,
496:       target: CONFIG.combat.goldPerHourTarget,
497:       history: eco.history
498:     };
499:   }
