512:   hasInventorySpace() {
513:     return this.inventoryCount() < this.inventoryCap();
514:   }
515: 
516:   addItem(item) {
517:     if (!item) return false;
518:     if (!this.hasInventorySpace()) {
519:       Events.emit('toast', { msg: 'Inventory full. Sell or store something.', type: 'warn' });
520:       return false;
521:     }
522:     if (item.kind === 'stone') {
523:       this.data.stones.push(item);
524:     } else if (item.kind === 'material') {
525:       const stack = this.data.inventory.find(i => i.kind === 'material' && i.materialId === item.materialId);
526:       if (stack) stack.count += item.count;
527:       else this.data.inventory.push(item);
528:       this.onCollect(item.materialId, item.count);
529:     } else {
530:       this.data.inventory.push(item);
531:     }
532:     this._invalidate();
533:     Events.emit('inventory', this.data.inventory);
534:     return true;
535:   }
536: 
537:   addMaterial(materialId, count = 1) {
538:     const mat = MATERIALS[materialId];
539:     if (!mat) return false;
540:     const stack = this.data.inventory.find(i => i.kind === 'material' && i.materialId === materialId);
541:     if (stack) {
542:       stack.count += count;
543:     } else {
544:       if (!this.hasInventorySpace()) {
545:         Events.emit('toast', { msg: 'Inventory full — material left behind.', type: 'warn' });
546:         return false;
547:       }
548:       this.data.inventory.push({ uid: uid('mat'), kind: 'material', materialId, name: mat.name, icon: mat.icon, desc: mat.desc, count });
549:     }
550:     this.onCollect(materialId, count);
551:     Events.emit('inventory', this.data.inventory);
552:     return true;
553:   }
554: 
555:   countMaterial(materialId) {
556:     return this.data.inventory.filter(i => i.kind === 'material' && i.materialId === materialId)
557:       .reduce((s, i) => s + i.count, 0);
558:   }
559: 
560:   removeMaterial(materialId, count = 1) {
561:     let left = count;
562:     for (const item of this.data.inventory) {
563:       if (item.kind !== 'material' || item.materialId !== materialId) continue;
564:       const take = Math.min(left, item.count);
565:       item.count -= take;
566:       left -= take;
567:       if (left <= 0) break;
568:     }
569:     this.data.inventory = this.data.inventory.filter(i => i.kind !== 'material' || i.count > 0);
570:     this._invalidate();
571:     Events.emit('inventory', this.data.inventory);
572:     return left === 0;
573:   }
574: 
575:   addStone(stone) {
576:     if (!this.hasInventorySpace()) {
577:       Events.emit('toast', { msg: 'Stone bag full.', type: 'warn' });
578:       return false;
579:     }
580:     stone.kind = 'stone';
581:     this.data.stones.push(stone);
582:     Events.emit('stones', this.data.stones);
583:     return true;
584:   }
585: 
586:   removeStone(uidValue) {
587:     const idx = this.data.stones.findIndex(s => s.uid === uidValue);
588:     if (idx < 0) return null;
589:     return this.data.stones.splice(idx, 1)[0];
590:   }
