592:   findItem(uidValue) {
593:     return this.data.inventory.find(i => i.uid === uidValue)
594:       || this.data.stones.find(i => i.uid === uidValue)
595:       || Object.values(this.data.equipped).find(i => i?.uid === uidValue)
596:       || this.data.storage.find(i => i.uid === uidValue)
