600:   // ------------------------------------------------------------
601:   // equipment
602:   // ------------------------------------------------------------
603:   createEquip(opts = {}) {
604:     const classId = opts.classId || this.char?.classId || 'warrior';
605:     const faction = opts.faction || this.char?.faction || 'angel';
606:     const slot = opts.slot || 'weapon';
607:     const rarity = opts.rarity || 'common';
608:     const tier = opts.tier || 3;
609:     const level = Math.max(1, Math.round(opts.level || this.char?.level || 1));
610:     const rng = makeRng(uid('roll'));
611:     const rDef = RARITIES[rarity];
612:     const tDef = TIERS[tier];
613:     const slotDef = SLOTS.find(s => s.id === slot);
614:     const scale = (0.75 + level * 0.075) * rDef.statMult * tDef.mult;
615:     const weights = STAT_WEIGHTS[slot];
616:     const stats = { atk: 0, def: 0, str: 0, int: 0, dex: 0, vit: 0, crit: 0 };
617: 
618:     const dmgBase = slot === 'weapon' ? (8 + level * 2.3) * (ITEM_BASE[classId].weapon.dmg) : 0;
619:     if (dmgBase) stats.atk = Math.round(dmgBase * scale * (0.9 + rng.next() * 0.2));
620:     if (weights.def > 0) stats.def = Math.round(slotDef.base * (0.7 + level * 0.055) * scale * weights.def * 2.1);
621:     stats[CLASSES[classId].primary] = Math.round((2 + level * 0.55) * scale * weights.primary * 1.7);
622:     stats.vit = Math.round((1.5 + level * 0.32) * scale * weights.vit * 1.4);
623:     if (weights.crit > 0) {
624:       const crit = (0.0015 + level * 0.00012) * scale * weights.crit * 2.2;
625:       stats.crit = Math.round(crit * 1000) / 1000;
626:     }
627: 
628:     // rarity affixes add extra primary/vitality/crit
629:     for (let i = 0; i < (rDef.affixes || 0); i++) {
630:       const pick = rng.pick(['primary', 'vit', 'crit', 'def']);
631:       if (pick === 'primary') stats[CLASSES[classId].primary] += Math.max(1, Math.round(level * 0.5 * rDef.statMult * 0.5));
632:       else if (pick === 'vit') stats.vit += Math.max(1, Math.round(level * 0.4 * rDef.statMult * 0.5));
633:       else if (pick === 'crit') stats.crit = Math.round((stats.crit + 0.004 * rDef.statMult) * 1000) / 1000;
634:       else stats.def += Math.max(1, Math.round(level * 0.7 * rDef.statMult * 0.4));
635:     }
636: 
637:     const baseNames = CLASS_ITEM_NAMES[classId][slot];
638:     const baseName = rng.pick(baseNames);
639:     const prefixSet = rng.chance(0.5) ? FACTION_ITEM_PREFIX[faction] : RARITY_PREFIX[rarity];
640:     const prefix = rng.pick(prefixSet);
641:     const name = `${prefix} ${baseName}${tier === 1 ? ' of Ascension' : tier === 2 ? ' of Power' : ''}`;
642:     const value = Math.round(slotDef.base * (5 + level * 1.9) * rDef.value * tDef.mult * 3.2);
643:     return {
644:       uid: uid('eq'), kind: 'equip', slot, classId, faction, rarity, tier, level,
645:       name, stats, bonuses: [], createdAt: Date.now(), value,
646:       icon: slotDef.icon
647:     };
648:   }
649: 
650:   rarityRoll() {
651:     return weightedPick(makeRng(uid('r')), CONFIG.drops.rarityWeights);
652:   }
653: 
654:   rollEquipmentDrop(monster, opts = {}) {
655:     const rng = makeRng(uid('drop'));
656:     const cls = rng.chance(opts.preferPlayer === false ? 0.25 : 0.55) ? this.char.classId : rng.pick(['warrior', 'mage', 'archer']);
657:     const fac = rng.chance(0.55) ? this.char.faction : rng.pick(['angel', 'demon']);
658:     const slot = rng.pick(SLOTS).id;
659:     const rarity = this.rarityRoll();
660:     const level = Math.max(1, Math.min(60, Math.round((monster?.level || this.char.level) * 0.9 + 1)));
661:     return this.createEquip({ slot, rarity, tier: CONFIG.drops.dropTier, classId: cls, faction: fac, level });
662:   }
663: 
664:   rollStone(monster) {
665:     const rng = makeRng(uid('stone'));
666:     const classId = rng.chance(0.55) ? this.char.classId : rng.pick(['warrior', 'mage', 'archer']);
667:     const primary = CLASSES[classId].primary;
668:     const stat = rng.pick([primary, primary, 'vit', 'crit']);
669:     let tier = 1;
670:     const lv = monster?.level || 1;
671:     if (lv >= 38) tier = 3; else if (lv >= 18) tier = 2;
672:     const t = [{}, { mult: 1, name: 'Lesser' }, { mult: 1.65, name: 'Greater' }, { mult: 2.5, name: 'Sovereign' }][tier];
673:     let value;
674:     if (stat === 'crit') value = Math.round((0.6 + rng.next() * 0.8) * t.mult * 100) / 100;
675:     else if (stat === 'vit') value = Math.round((5 + rng.next() * 5) * t.mult);
676:     else value = Math.round((4 + rng.next() * 4) * t.mult);
677:     const sdef = BONUS_STATS[stat];
678:     return {
679:       uid: uid('st'), kind: 'stone', classId, stat, value, tier,
680:       name: `${t.name} ${sdef.name} Stone`, icon: sdef.icon,
681:       desc: `${sdef.icon} +${value}${stat === 'crit' ? '%' : ''} ${sdef.name} — boss stone, tradeable.`
682:     };
683:   }
