685:   canEquip(item) {
686:     if (!item || item.kind !== 'equip') return { ok: false, reason: 'Not equipment' };
687:     if (item.classId !== this.char.classId) {
688:       return { ok: false, reason: `${CLASSES[item.classId].name}s only` };
689:     }
690:     if (item.faction !== this.char.faction) {
691:       return { ok: false, reason: `${FACTIONS[item.faction].name} only` };
692:     }
693:     return { ok: true };
694:   }
