696:   equip(itemUid) {
697:     const item = this.data.inventory.find(i => i.uid === itemUid);
698:     if (!item || item.kind !== 'equip') return { ok: false, msg: 'Item not found.' };
699:     const check = this.canEquip(item);
700:     if (!check.ok) return { ok: false, msg: `Cannot equip: ${check.reason}.` };
701:     const current = this.data.equipped[item.slot];
702:     this.data.inventory = this.data.inventory.filter(i => i.uid !== itemUid);
703:     this.data.equipped[item.slot] = item;
704:     if (current) this.data.inventory.push(current);
705:     this._invalidate();
