714:     const item = this.data.equipped[slot];
715:     if (!item) return { ok: false, msg: 'Nothing equipped there.' };
716:     if (!this.hasInventorySpace()) return { ok: false, msg: 'Inventory full.' };
717:     this.data.equipped[slot] = null;
718:     this.data.inventory.push(item);
719:     this._invalidate();
720:     this.recalcHP();
721:     Events.emit('equipment', this.data.equipped);
722:     Events.emit('inventory', this.data.inventory);
723:     return { ok: true, msg: `Unequipped ${item.name}.` };
