726:   sellItem(itemUid) {
727:     const idx = this.data.inventory.findIndex(i => i.uid === itemUid);
728:     if (idx < 0) return { ok: false, msg: 'Item not found.' };
729:     const item = this.data.inventory[idx];
730:     if (item.kind === 'material') {
731:       const total = Math.round(150 * item.count * (item.materialId === 'mat_primordial_core' ? 500 : 1));
732:       this.removeMaterial(item.materialId, item.count);
733:       this.addGold(total, 'npc_sale', `Sold ${item.count} × ${item.name}`);
734:       return { ok: true, msg: `Sold ${item.name} for ${fmt(total)} gold.`, gold: total };
735:     }
736:     if (item.kind !== 'equip') return { ok: false, msg: 'This cannot be sold here.' };
737:     const price = Math.max(1, Math.round((item.value || 100) * CONFIG.economy.npcSellRate));
738:     this.data.inventory.splice(idx, 1);
739:     this.addGold(price, 'npc_sale', `Sold ${item.name}`);
740:     this._invalidate();
741:     Events.emit('inventory', this.data.inventory);
742:     return { ok: true, msg: `Sold ${item.name} for ${fmt(price)} gold.`, gold: price };
743:   }
