745:   // ------------------------------------------------------------
746:   // fusion / crafting
747:   // ------------------------------------------------------------
748:   fusionKey(item) {
749:     return [item.classId, item.faction, item.slot, item.rarity, item.tier].join('|');
750:   }
751: 
752:   fusionGroups() {
753:     const map = new Map();
754:     for (const item of this.data.inventory) {
755:       if (item.kind !== 'equip') continue;
756:       const key = this.fusionKey(item);
757:       if (!map.has(key)) map.set(key, { key, items: [], sample: item });
758:       map.get(key).items.push(item);
759:     }
760:     return [...map.values()].filter(g => g.items.length >= CONFIG.fusion.requirementCount)
761:       .sort((a, b) => RARITIES[b.sample.rarity].order - RARITIES[a.sample.rarity].order || a.sample.tier - b.sample.tier);
762:   }
763: 
764:   fusionCost(item) {
765:     const costs = CONFIG.fusion.costs[item.rarity];
766:     if (!costs) return null;
767:     if (item.tier > 1) return costs[item.tier === 3 ? 't3t2' : 't2t1'];
768:     if (item.rarity === 'divine') return null;
769:     if (item.rarity === 'legendary') return CONFIG.fusion.special.mythicFusion;
770:     if (item.rarity === 'mythic') return CONFIG.fusion.special.divineFusion;
771:     return costs.next;
772:   }
773: 
774:   fusionNext(item) {
775:     if (item.tier > 1) return { rarity: item.rarity, tier: item.tier - 1 };
776:     const idx = RARITY_ORDER.indexOf(item.rarity);
777:     if (idx < 0 || idx >= RARITY_ORDER.length - 1) return null;
778:     return { rarity: RARITY_ORDER[idx + 1], tier: 3 };
779:   }
780: 
781:   fuseGroup(key) {
782:     const group = this.fusionGroups().find(g => g.key === key);
783:     if (!group) return { ok: false, msg: 'You need 4 identical items.' };
784:     const items = group.items.slice(0, 4);
785:     const sample = items[0];
786:     const cost = this.fusionCost(sample);
787:     if (cost == null) return { ok: false, msg: 'Divine T1 is the final tier — no further fusion.' };
788:     const next = this.fusionNext(sample);
789:     if (!next) return { ok: false, msg: 'This item cannot be fused further.' };
790:     if (!this.spendGold(cost, 'fusion', `${sample.rarity} ${sample.slot} fusion`)) {
791:       return { ok: false, msg: `Not enough gold. Need ${fmt(cost)}.` };
792:     }
793:     // preserve all bonuses without destroying stones: keep best 3, refund the rest as loose stones
794:     const bonusMap = new Map();
795:     for (const it of items) for (const b of it.bonuses || []) {
796:       const prev = bonusMap.get(b.stat);
797:       if (!prev || b.value > prev.value) bonusMap.set(b.stat, b);
798:     }
799:     const kept = [...bonusMap.values()].slice(0, 3);
800:     const refunded = [...bonusMap.values()].slice(3);
801:     const removeIds = new Set(items.map(i => i.uid));
802:     this.data.inventory = this.data.inventory.filter(i => !removeIds.has(i.uid));
803:     const result = this.createEquip({
804:       slot: sample.slot, rarity: next.rarity, tier: next.tier,
805:       classId: sample.classId, faction: sample.faction,
806:       level: Math.max(sample.level, this.char.level)
807:     });
808:     result.bonuses = kept;
809:     this.data.inventory.push(result);
810:     for (const b of refunded) {
811:       const stat = BONUS_STATS[b.stat];
812:       this.addStone({ uid: uid('st'), kind: 'stone', classId: result.classId, stat: b.stat, value: b.value, tier: 3, name: `Sovereign ${stat.name} Stone`, icon: stat.icon, desc: `Refunded bonus. ${b.value} ${stat.name}.` });
813:     }
814:     this._invalidate();
815:     Events.emit('inventory', this.data.inventory);
816:     Events.emit('stones', this.data.stones);
817:     Events.emit('toast', { msg: `Fusion complete: ${result.name} (${TIERS[next.tier].name})`, type: 'success' });
818:     return { ok: true, item: result, msg: `Forged ${result.name}!` };
819:   }
820: 
821:   craftLegendary(slot = 'weapon') {
822:     const cost = CONFIG.fusion.special.legendaryCraft;
823:     const cores = this.countMaterial('mat_primordial_core');
824:     if (cores < CONFIG.fusion.legendaryCores) {
825:       return { ok: false, msg: `Need ${CONFIG.fusion.legendaryCores} Primordial Cores (you have ${cores}). Defeat bosses to obtain them.` };
826:     }
827:     const mats = REGION_ORDER.map(r => REGIONS[r].material.id).reduce((s, id) => s + this.countMaterial(id), 0);
828:     if (mats < CONFIG.fusion.legendaryMaterials) {
829:       return { ok: false, msg: `Need ${CONFIG.fusion.legendaryMaterials} rare region materials (you have ${mats}).` };
830:     }
831:     if (!this.spendGold(cost, 'legendary_craft', 'Legendary crafting')) {
832:       return { ok: false, msg: `Not enough gold. Need ${fmt(cost)}.` };
833:     }
834:     this.removeMaterial('mat_primordial_core', CONFIG.fusion.legendaryCores);
835:     let left = CONFIG.fusion.legendaryMaterials;
836:     for (const r of REGION_ORDER) {
837:       if (left <= 0) break;
838:       const id = REGIONS[r].material.id;
839:       const have = this.countMaterial(id);
840:       const take = Math.min(have, left);
841:       if (take > 0) { this.removeMaterial(id, take); left -= take; }
842:     }
843:     const item = this.createEquip({ slot, rarity: 'legendary', tier: 3, classId: this.char.classId, faction: this.char.faction, level: this.char.level });
844:     this.data.inventory.push(item);
845:     this._invalidate();
846:     Events.emit('inventory', this.data.inventory);
847:     Events.emit('toast', { msg: `Legendary crafted: ${item.name}`, type: 'success' });
848:     return { ok: true, item, msg: `The forge sings. ${item.name} is yours.` };
849:   }
