851:   // ------------------------------------------------------------
852:   // bonuses / enchanting
853:   // ------------------------------------------------------------
854:   enchantCost(stone) {
855:     return stone.tier === 3 ? 40000 : stone.tier === 2 ? 15000 : 5000;
856:   }
857: 
858:   applyStone(itemUidToEnchant, stoneUid, replaceIndex = -1) {
859:     const item = this.findItem(itemUidToEnchant);
860:     const stone = this.data.stones.find(s => s.uid === stoneUid);
861:     if (!item || item.kind !== 'equip') return { ok: false, msg: 'Select a valid item.' };
862:     if (!stone) return { ok: false, msg: 'Select a boss stone.' };
863:     if (item.classId !== stone.classId) return { ok: false, msg: `This stone only fits ${CLASSES[stone.classId].name} equipment.` };
864:     item.bonuses = item.bonuses || [];
865:     const cost = this.enchantCost(stone);
866:     if (item.bonuses.length >= 3 && replaceIndex < 0) {
867:       return { ok: false, msg: 'This item already has 3 bonuses. Choose one to replace.' };
868:     }
869:     if (!this.spendGold(cost, 'enchant', `Applied ${stone.name}`)) {
870:       return { ok: false, msg: `Not enough gold. Need ${fmt(cost)}.` };
871:     }
872:     this.data.stones = this.data.stones.filter(s => s.uid !== stoneUid);
873:     let replaced = null;
874:     if (item.bonuses.length >= 3 && replaceIndex >= 0) {
875:       replaced = item.bonuses.splice(replaceIndex, 1)[0];
876:     }
877:     item.bonuses.push({ stat: stone.stat, value: stone.value, tier: stone.tier });
878:     if (replaced) {
879:       const stat = BONUS_STATS[replaced.stat];
880:       this.addStone({
881:         uid: uid('st'), kind: 'stone', classId: item.classId, stat: replaced.stat, value: replaced.value,
882:         tier: replaced.tier || 3, name: `Recovered ${stat.name} Stone`, icon: stat.icon,
883:         desc: `Recovered bonus. +${replaced.value} ${stat.name}.`
884:       });
885:     }
886:     this._invalidate();
887:     this.recalcHP();
888:     Events.emit('inventory', this.data.inventory);
889:     Events.emit('stones', this.data.stones);
890:     Events.emit('equipment', this.data.equipped);
891:     return { ok: true, msg: `${stone.name} bound to ${item.name}. No item was destroyed.`, replaced };
892:   }
