894:   // ------------------------------------------------------------
895:   // quests
896:   // ------------------------------------------------------------
897:   questState(id) {
898:     if (this.data.quests.completed.includes(id)) return 'completed';
899:     if (this.data.quests.active.some(q => q.id === id)) return 'active';
900:     return 'available';
901:   }
902: 
903:   activeQuest(id) { return this.data.quests.active.find(q => q.id === id); }
904: 
905:   questProgress(q) {
906:     if (q.type === 'level') return Math.min(this.char.level, q.required);
907:     if (q.type === 'collect') return Math.min(this.countMaterial(q.target), q.required);
908:     return Math.min(this.activeQuest(q.id)?.progress || 0, q.required);
909:   }
910: 
911:   canAcceptQuest(def) {
912:     if (!def) return { ok: false, reason: 'Unknown quest.' };
913:     if (this.questState(def.id) !== 'available') return { ok: false, reason: 'Quest already taken or completed.' };
914:     if (this.char.level < def.level) return { ok: false, reason: `Requires level ${def.level}.` };
915:     const missing = (def.requires || []).filter(id => !this.data.quests.completed.includes(id));
916:     if (missing.length) return { ok: false, reason: 'Prerequisite quest incomplete.' };
917:     return { ok: true };
918:   }
919: 
920:   acceptQuest(id) {
921:     const def = QUESTS.find(q => q.id === id);
922:     const check = this.canAcceptQuest(def);
923:     if (!check.ok) return { ok: false, msg: check.reason };
924:     const q = { id, progress: 0, acceptedAt: Date.now() };
925:     if (def.type === 'collect') q.progress = Math.min(def.required, this.countMaterial(def.target));
926:     this.data.quests.active.push(q);
927:     Events.emit('quests', this.data.quests);
928:     return { ok: true, msg: `Quest accepted: ${def.title}` };
929:   }
930: 
931:   abandonQuest(id) {
932:     const before = this.data.quests.active.length;
933:     this.data.quests.active = this.data.quests.active.filter(q => q.id !== id);
934:     if (before !== this.data.quests.active.length) {
935:       Events.emit('quests', this.data.quests);
936:       return { ok: true, msg: 'Quest abandoned.' };
937:     }
938:     return { ok: false, msg: 'Quest not active.' };
939:   }
940: 
941:   isQuestComplete(def) {
942:     if (!def) return false;
943:     return this.questProgress(def) >= def.required;
944:   }
945: 
946:   onKill(monsterId) {
947:     this.char.kills++;
948:     for (const q of this.data.quests.active) {
949:       const def = QUESTS.find(d => d.id === q.id);
950:       if (!def) continue;
951:       if (def.type === 'kill' && def.target === monsterId) {
952:         q.progress = Math.min(def.required, (q.progress || 0) + 1);
953:       }
954:     }
955:     if (MONSTERS[monsterId]?.boss) this.char.bosses++;
956:     Events.emit('quests', this.data.quests);
957:   }
