57: function idx(size, x, y) { return y * size + x; }
58: function inBounds(world, x, y) { return x >= 0 && y >= 0 && x < world.size && y < world.size; }
59: 
60: function tileAt(world, x, y) {
61:   if (!inBounds(world, x, y)) return null;
62:   return world.tiles[idx(world.size, Math.floor(x), Math.floor(y))];
63: }
64: 
65: function setTile(world, x, y, type, variant) {
66:   if (!inBounds(world, x, y)) return;
67:   const t = world.tiles[idx(world.size, x, y)];
68:   if (!t) return;
69:   t.type = type;
70:   if (variant != null) t.variant = variant;
71:   if (type === 'water' || type === 'void') t.blocked = true;
72: }
73: 
74: function markDisc(world, cx, cy, radius, type, onlyIf = null) {
75:   const r = Math.ceil(radius);
76:   for (let y = Math.floor(cy) - r; y <= Math.ceil(cy) + r; y++) {
77:     for (let x = Math.floor(cx) - r; x <= Math.ceil(cx) + r; x++) {
78:       if (!inBounds(world, x, y)) continue;
79:       if (Math.hypot(x + 0.5 - cx, y + 0.5 - cy) > radius) continue;
80:       const t = world.tiles[idx(world.size, x, y)];
81:       if (!t || t.type === 'water') continue;
82:       if (onlyIf && !onlyIf(t)) continue;
83:       setTile(world, x, y, type);
84:     }
85:   }
86: }
87: 
88: function markPath(world, x1, y1, x2, y2, width = 1.5) {
89:   const steps = Math.ceil(Math.max(Math.abs(x2 - x1), Math.abs(y2 - y1)) * 2);
90:   for (let i = 0; i <= steps; i++) {
91:     const t = i / steps;
92:     // slight winding for a hand-painted feel
93:     const wobble = Math.sin(t * Math.PI * 3) * 0.9;
94:     const x = x1 + (x2 - x1) * t + wobble * 0.35;
95:     const y = y1 + (y2 - y1) * t - wobble * 0.35;
96:     markDisc(world, x + 0.5, y + 0.5, width, 'path', tile => tile.type !== 'water');
97:   }
98: }
99: 
100: function propBlocked(world, x, y, radius = 0.18) {
101:   for (const p of world.blockingProps) {
102:     if (Math.abs(p.x - x) > 2 || Math.abs(p.y - y) > 2) continue;
103:     if (Math.hypot(p.x - x, p.y - y) < p.block + radius) return true;
104:   }
105:   return false;
106: }
107: 
108: function tryPlaceProp(world, rng, type, x, y, options = {}) {
109:   const def = PROP_DEFS[type] || PROP_DEFS.rock;
110:   if (!inBounds(world, Math.floor(x), Math.floor(y))) return null;
111:   if (world.tiles[idx(world.size, Math.floor(x), Math.floor(y))]?.type === 'water') return null;
112:   const p = {
113:     pid: uid('p'), type, kind: def.kind, x, y,
114:     block: options.nonBlocking ? 0 : def.block, height: def.height,
115:     variant: rng.int(0, 999), flip: rng.chance(0.5), scale: options.scale || (0.9 + rng.next() * 0.25),
116:     fixed: !!options.fixed, glow: options.glow || null
117:   };
118:   world.props.push(p);
119:   if (p.block > 0) world.blockingProps.push(p);
120:   return p;
121: }
122: 
123: function regionClears(world, x, y, rng, cfg) {
124:   if (tileAt(world, x, y)?.type === 'water') return false;
125:   if (Math.hypot(x - world.village[0], y - world.village[1]) < cfg.villageClear) return false;
126:   if (Math.hypot(x - world.spawn.x, y - world.spawn.y) < 2.2) return false;
127:   if (Math.hypot(x - world.lair[0], y - world.lair[1]) < 5.5) return false;
128:   for (const n of world.npcs) if (Math.hypot(x - n.x, y - n.y) < 1.6) return false;
129:   if (propBlocked(world, x, y, 1.0)) return false;
130:   return true;
131: }
