133: function placeVillage(world, region, rng) {
134:   const [vx, vy] = world.village;
135:   // plaza
136:   markDisc(world, vx, vy, 6.4, 'plaza', tile => tile.type !== 'water');
137:   markDisc(world, vx, vy, 3.0, 'plaza_light', tile => tile.type !== 'water');
138: 
139:   const houses = [
140:     [-5.4, -4.4, 'house'], [5.2, -4.6, 'house'], [-5.8, 3.6, 'house'], [5.5, 3.8, 'house']
141:   ];
142:   for (const [dx, dy] of houses) {
143:     tryPlaceProp(world, rng, 'house', vx + dx, vy + dy, { fixed: true, scale: 1 });
144:   }
145:   tryPlaceProp(world, rng, 'well', vx - 0.2, vy + 1.2, { fixed: true });
146:   tryPlaceProp(world, rng, 'campfire', vx + 1.0, vy - 0.6, { fixed: true });
147:   for (const [dx, dy] of [[-2.5, 5.3], [2.6, 5.5], [-7.0, -0.4], [7.0, -0.2]]) {
148:     tryPlaceProp(world, rng, 'banner', vx + dx, vy + dy, { fixed: true, scale: 1 });
149:   }
150:   for (const [dx, dy] of [[3.9, -3.8], [-4.3, 4.6], [4.8, 5.1], [-5.5, -1.0]]) {
151:     tryPlaceProp(world, rng, 'crate', vx + dx, vy + dy, { fixed: true });
152:   }
153:   tryPlaceProp(world, rng, 'stall', vx + 4.5, vy - 2.6, { fixed: true });
154:   tryPlaceProp(world, rng, 'signpost', vx + 1.2, vy + 5.4, { fixed: true, scale: 1 });
155: }
156: 
157: function placeLair(world, region, rng) {
158:   const [lx, ly] = world.lair;
159:   tryPlaceProp(world, rng, 'altar', lx, ly, { fixed: true, scale: 1 });
160:   tryPlaceProp(world, rng, 'gate', lx - 3.4, ly + 1.4, { fixed: true, scale: 1 });
161:   tryPlaceProp(world, rng, 'brazier', lx + 2.8, ly + 1.8, { fixed: true });
162:   tryPlaceProp(world, rng, 'brazier', lx - 2.6, ly - 1.6, { fixed: true });
163:   const themeProps = {
164:     greendale: ['oak', 'stump'], ironcrag: ['ore', 'boulder'], venomwood: ['mushroom', 'web'],
165:     mistgrave: ['gravestone', 'candle'], frostpeak: ['crystal', 'ice'], sunscorch: ['pillar', 'bones'],
166:     ashen: ['obsidian', 'spike'], tower: ['void_crystal', 'rune']
167:   }[region.id] || ['rock'];
168:   for (let i = 0; i < 10; i++) {
169:     const a = rng.next() * Math.PI * 2;
170:     const r = 3.5 + rng.next() * 5;
171:     tryPlaceProp(world, rng, themeProps[i % themeProps.length], lx + Math.cos(a) * r, ly + Math.sin(a) * r);
172:   }
173: }
174: 
175: function makeNodes(world, region, rng) {
176:   const nodes = [];
177:   const count = 8;
178:   for (let i = 0; i < count; i++) {
179:     let x, y, tries = 0;
180:     do {
181:       x = 2 + rng.next() * (world.size - 4);
182:       y = 2 + rng.next() * (world.size - 4);
183:       tries++;
184:     } while (tries < 60 && (!regionClears(world, x, y, rng, { villageClear: 5 }) || Math.hypot(x - world.lair[0], y - world.lair[1]) < 4));
185:     nodes.push({
186:       nid: uid('node'), kind: 'node', x, y, materialId: region.material.id,
187:       name: region.material.name, icon: region.material.icon,
188:       respawnAt: 0, variant: rng.int(0, 999), scale: 0.9 + rng.next() * 0.3
189:     });
190:   }
191:   return nodes;
192: }
