194: function makeHidden(world, region, rng) {
195:   const spots = [
196:     [3.2, world.size - 3.6], [world.size - 3.4, 3.2]
197:   ];
198:   return spots.map(([x, y], i) => ({
199:     hid: uid('hidden'), x, y, opened: false, kind: 'chest',
200:     loot: { gold: 1200 + region.levelRange[1] * 280, material: region.material.id, count: 2 + i },
201:     variant: rng.int(0, 999)
202:   }));
203: }
