205: export function buildWorld(regionId, opts = {}) {
206:   const region = REGIONS[regionId] || REGIONS.greendale;
207:   const size = region.size;
208:   const rng = makeRng(`aetheria:${regionId}:${opts.dungeonId || 'open'}`);
209:   const dungeon = opts.dungeonId ? DUNGEONS.find(d => d.id === opts.dungeonId) : null;
210:   const world = {
211:     regionId, region, size, dungeon, mode: dungeon ? 'dungeon' : 'world',
212:     props: [], blockingProps: [], npcs: [], nodes: [], hidden: [], enemies: [],
213:     tiles: new Array(size * size),
214:     village: [...region.village], lair: [...region.lair],
215:     spawn: { x: region.spawn[0], y: region.spawn[1] },
216:     bossId: region.boss, time: 0
217:   };
218: 
219:   // ground tiles
220:   for (let y = 0; y < size; y++) {
221:     for (let x = 0; x < size; x++) {
222:       const edge = x === 0 || y === 0 || x === size - 1 || y === size - 1;
223:       let type = region.ground;
224:       const n = rng.next();
225:       if (n > 0.93) type = 'ground2';
226:       else if (n > 0.83) type = 'ground3';
227:       if (edge && region.ground === 'void') type = 'void';
228:       world.tiles[idx(size, x, y)] = { x, y, type, variant: rng.int(0, 999), blocked: type === 'void' };
229:     }
230:   }
231: 
232:   // water features
233:   const pond = {
234:     greendale: [26, 7, 3.3], ironcrag: [7, 26, 2.6], venomwood: [27, 6, 3.6], mistgrave: [7, 27, 3.2],
235:     frostpeak: [27, 7, 3.4], sunscorch: [7, 28, 2.8], ashen: [28, 7, 3.1], tower: [7, 7, 2.6]
236:   }[regionId];
237:   if (pond) {
238:     const [px, py, r] = pond;
239:     for (let y = Math.floor(py - r - 1); y <= Math.ceil(py + r + 1); y++) {
240:       for (let x = Math.floor(px - r - 1); x <= Math.ceil(px + r + 1); x++) {
241:         if (!inBounds(world, x, y)) continue;
242:         if (Math.hypot(x + 0.5 - px, y + 0.5 - py) <= r) {
243:           setTile(world, x, y, region.ground === 'sand' ? 'water' : 'water');
244:         }
245:       }
246:     }
247:     // shore
248:     markDisc(world, px, py, r + 0.7, 'shore', null);
249:   }
250: 
251:   // paths
252:   const [vx, vy] = world.village;
253:   markPath(world, world.spawn.x, world.spawn.y, vx + 1.5, vy + 4.5, 1.3);
254:   markPath(world, vx, vy, world.lair[0] - 2, world.lair[1] - 2, 1.3);
255:   markPath(world, vx - 5, vy + 1, size - 4, 4, 0.85);
256:   markPath(world, 4, vy - 3, size - 4, size - 4, 0.85);
257: 
258:   // NPCs
259:   const localNpcs = Object.values(NPCS).filter(n => n.region === regionId);
260:   const npcList = [...localNpcs];
261:   if (regionId !== 'greendale') {
262:     const provision = {
263:       id: `provision_${regionId}`, name: 'Camp Provisioner', role: 'Potion Merchant', icon: '⚗',
264:       color: '#69c5a8', region: regionId, dx: 3.6, dy: 1.4, greeting: 'Potions, tonics and bandages. The frontier is expensive.'
265:     };
266:     const forge = {
267:       id: `forge_${regionId}`, name: 'Field Smith', role: 'Blacksmith', icon: '⚒',
268:       color: '#c17a4a', region: regionId, dx: -3.7, dy: 1.6, greeting: 'A field forge is still a forge. Bring me four of a kind.'
269:     };
270:     npcList.push(provision, forge);
271:   }
272:   for (const n of npcList) {
273:     world.npcs.push({
274:       ...n,
275:       x: clamp(vx + n.dx, 2, size - 3),
276:       y: clamp(vy + n.dy, 2, size - 3),
277:       facing: 1, anim: Math.random() * 10
278:     });
279:   }
280: 
281:   placeVillage(world, region, rng);
282:   placeLair(world, region, rng);
283: 
284:   // random scenery
285:   const propCount = Math.floor(size * 2.4);
286:   for (let i = 0; i < propCount * 3 && world.props.length < propCount; i++) {
287:     const type = rng.pick(region.props);
288:     const x = 1.4 + rng.next() * (size - 2.8);
289:     const y = 1.4 + rng.next() * (size - 2.8);
290:     if (!regionClears(world, x, y, rng, { villageClear: 7.2 })) continue;
291:     if (Math.hypot(x - world.lair[0], y - world.lair[1]) < 4.5) continue;
292:     tryPlaceProp(world, rng, type, x, y);
293:   }
294: 
295:   // extra roadside details
296:   for (let i = 0; i < 18; i++) {
297:     const type = rng.pick(['flowers', 'bush', 'stump', 'rubble', 'bone', 'signpost'].filter(t => region.props.includes(t) || Math.random() < 0.3));
298:     if (!type) continue;
299:     const x = 1.5 + rng.next() * (size - 3);
300:     const y = 1.5 + rng.next() * (size - 3);
301:     if (!regionClears(world, x, y, rng, { villageClear: 6.4 })) continue;
302:     tryPlaceProp(world, rng, type, x, y, { nonBlocking: true, scale: 0.8 + rng.next() * 0.4 });
303:   }
304: 
305:   world.nodes = makeNodes(world, region, rng);
306:   world.hidden = makeHidden(world, region, rng);
307: 
308:   if (dungeon) {
309:     // dungeon run: start at the lair threshold and face the boss
310:     world.spawn = { x: Math.max(2, world.lair[0] + 4.5), y: Math.max(2, world.lair[1] + 4.5) };
311:     world.dungeonStart = true;
312:   }
313: 
314:   // Scenery is placed procedurally and can overlap the configured spawn
315:   // (or the dungeon threshold). Nudge the spawn to the nearest walkable tile
316:   // so the player can never load inside a tree, house or pool of water.
317:   world.spawn = findSafeSpawn(world, world.spawn);
318:   return world;
319: }
320: 
321: function findSafeSpawn(world, origin) {
322:   if (!isBlocked(world, origin.x, origin.y, 0.26)) return { x: origin.x, y: origin.y };
323:   for (let radius = 0.5; radius <= 14; radius += 0.5) {
324:     const steps = Math.max(8, Math.ceil(radius * 8));
325:     for (let i = 0; i < steps; i++) {
326:       const a = (i / steps) * Math.PI * 2;
327:       const x = origin.x + Math.cos(a) * radius;
328:       const y = origin.y + Math.sin(a) * radius;
329:       if (x < 1.2 || y < 1.2 || x > world.size - 1.2 || y > world.size - 1.2) continue;
330:       if (!isBlocked(world, x, y, 0.26)) return { x, y };
331:     }
332:   }
333:   return { x: world.village[0], y: world.village[1] + 2 };
334: }
335: 
336: export function activeTileAt(world, x, y) {
337:   return tileAt(world, x, y);
338: }
339: 
340: export function isBlocked(world, x, y, radius = 0.22) {
341:   if (x < 1.1 || y < 1.1 || x > world.size - 1.1 || y > world.size - 1.1) return true;
342:   const tx = Math.floor(x), ty = Math.floor(y);
343:   const t = world.tiles[idx(world.size, clamp(tx, 0, world.size - 1), clamp(ty, 0, world.size - 1))];
344:   if (!t) return true;
345:   if (t.blocked || t.type === 'water' || t.type === 'void') return true;
346:   // check all tiles under the collision circle
347:   if (isTileBlocked(world, x + radius, y) || isTileBlocked(world, x - radius, y)
348:     || isTileBlocked(world, x, y + radius) || isTileBlocked(world, x, y - radius)) return true;
349:   return propBlocked(world, x, y, radius);
350: }
351: 
352: function isTileBlocked(world, x, y) {
353:   const t = tileAt(world, x, y);
354:   return !t || t.blocked || t.type === 'water' || t.type === 'void';
355: }
356: 
357: export function npcNear(world, x, y, radius = 2.3) {
358:   let best = null;
359:   let bestD = radius;
360:   for (const npc of world.npcs) {
361:     const d = Math.hypot(npc.x - x, npc.y - y);
362:     if (d < bestD) { bestD = d; best = npc; }
363:   }
364:   return best;
365: }
366: 
367: export function nodeNear(world, x, y, radius = 1.7) {
368:   let best = null, bestD = radius;
369:   for (const n of world.nodes) {
370:     if (n.respawnAt > Date.now()) continue;
371:     const d = Math.hypot(n.x - x, n.y - y);
372:     if (d < bestD) { bestD = d; best = n; }
373:   }
374:   return best;
375: }
376: 
377: export function hiddenNear(world, x, y, radius = 1.7) {
378:   let best = null, bestD = radius;
379:   for (const h of world.hidden) {
380:     if (h.opened) continue;
381:     const d = Math.hypot(h.x - x, h.y - y);
382:     if (d < bestD) { bestD = d; best = h; }
383:   }
384:   return best;
385: }
