387: function safeSpot(world, rng, minFromVillage = 6, avoidLair = 4) {
388:   for (let i = 0; i < 100; i++) {
389:     const x = 2.4 + rng.next() * (world.size - 4.8);
390:     const y = 2.4 + rng.next() * (world.size - 4.8);
391:     if (isBlocked(world, x, y, 0.35)) continue;
392:     if (Math.hypot(x - world.village[0], y - world.village[1]) < minFromVillage) continue;
393:     if (Math.hypot(x - world.lair[0], y - world.lair[1]) < avoidLair) continue;
394:     if (Math.hypot(x - world.spawn.x, y - world.spawn.y) < 3) continue;
395:     return { x, y };
396:   }
397:   return { x: world.size / 2 + 4, y: world.size / 2 + 4 };
398: }
