400: export function createEnemy(world, typeId, x, y, opts = {}) {
401:   const def = MONSTERS[typeId];
402:   if (!def) return null;
403:   const elite = opts.elite ?? false;
404:   const scale = (opts.scale || 1) * (elite ? 1.55 : 1);
405:   return {
406:     eid: uid('mob'), type: typeId, def,
407:     x, y, homeX: x, homeY: y,
408:     hp: Math.round(def.hp * scale), maxHp: Math.round(def.hp * scale),
409:     level: opts.level || def.level,
410:     atk: def.atk * scale,
411:     xp: Math.round(def.xp * (elite ? 1.7 : 1)),
412:     gold: Math.round(def.gold * (elite ? 1.9 : 1)),
413:     elite, boss: def.boss, scale: (def.scale || 1) * (elite ? 1.18 : 1),
414:     alive: true, respawnAt: 0, respawnType: typeId, respawnElite: elite,
415:     target: null, attackCd: 0, hitFlash: 0, state: 'idle', wanderT: 0,
416:     wanderX: x, wanderY: y, facing: 1, anim: Math.random() * 10,
417:     aggroed: false, deadT: 0, chase: false
418:   };
419: }
420: 
421: export function populateEnemies(world, opts = {}) {
422:   const rng = makeRng(`mobs:${world.regionId}:${world.mode}:${Date.now()}`);
423:   const enemies = [];
424:   const dungeon = world.dungeon;
425:   if (dungeon) {
426:     for (let i = 0; i < 16; i++) {
427:       const type = rng.pick(dungeon.minions);
428:       const spot = safeSpot(world, rng, 2, 2.5);
429:       const e = createEnemy(world, type, spot.x, spot.y, { elite: rng.chance(0.18), level: dungeon.level });
430:       if (e) enemies.push(e);
431:     }
432:     const boss = createEnemy(world, dungeon.boss, world.lair[0] - 1.2, world.lair[1] - 1.2, { level: dungeon.level + 2, scale: 1.18 });
433:     if (boss) enemies.push(boss);
434:   } else {
435:     const normals = 15;
436:     for (let i = 0; i < normals; i++) {
437:       const type = rng.pick(world.region.monsters);
438:       const spot = safeSpot(world, rng);
439:       const elite = rng.chance(0.07);
440:       const e = createEnemy(world, type, spot.x, spot.y, { elite });
441:       if (e) enemies.push(e);
