549:   // ------------------------------------------------------------
550:   // DEATH & LOOT
551:   // ------------------------------------------------------------
552:   killEnemy(enemy) {
553:     if (!enemy.alive) return;
554:     enemy.alive = false;
555:     enemy.hp = 0;
556:     enemy.deadT = Date.now();
557:     const def = enemy.def;
558:     const boss = def.boss;
559:     enemy.respawnAt = Date.now() + (boss ? CONFIG.combat.bossRespawnSeconds : enemy.elite ? CONFIG.combat.eliteRespawnSeconds : CONFIG.combat.respawnSeconds) * 1000;
560:     this.state.onKill(enemy.type);
561: 
562:     const rawGold = Math.round(enemy.gold * (CONFIG.drops.goldVariance[0] + Math.random() * (CONFIG.drops.goldVariance[1] - CONFIG.drops.goldVariance[0])));
563:     this.state.addGold(rawGold, 'monster', def.name);
564:     this.state.gainXp(enemy.xp, 'combat');
565:     this.addEffect({ type: 'dmg', x: enemy.x, y: enemy.y, text: `+${fmt(rawGold)}g`, color: '#ffd166', life: 1.2, maxLife: 1.2, offset: 16 });
566:     this.sfx.play('coin');
567: 
568:     const drops = [];
569:     // equipment (always T3)
570:     let gearRolls = 0;
571:     if (Math.random() < CONFIG.drops.equipmentChance) gearRolls = 1;
572:     if (boss) gearRolls = 1 + (Math.random() < (CONFIG.drops.bossEquipmentChance - 1) ? 1 : 0);
573:     if (enemy.elite && Math.random() < 0.25) gearRolls = Math.max(gearRolls, 1);
574:     for (let i = 0; i < gearRolls; i++) {
575:       const item = this.state.rollEquipmentDrop({ level: enemy.level }, { preferPlayer: boss });
576:       if (item) {
577:         this.groundLoot.push({ lid: uid('loot'), x: enemy.x + (Math.random() - 0.5) * 0.9, y: enemy.y + (Math.random() - 0.5) * 0.9, item, kind: 'equip', expires: Date.now() + 120000, bob: Math.random() * 6 });
578:         drops.push(item.name);
579:       }
580:     }
581:     // boss stones
582:     if (Math.random() < CONFIG.drops.stoneChance || boss) {
583:       const count = boss ? (enemy.level >= 40 ? 2 : 1) : 1;
584:       for (let i = 0; i < count; i++) {
585:         const stone = this.state.rollStone({ level: enemy.level });
586:         this.groundLoot.push({ lid: uid('loot'), x: enemy.x + (Math.random() - 0.5) * 1.1, y: enemy.y + (Math.random() - 0.5) * 1.1, item: stone, kind: 'stone', expires: Date.now() + 120000, bob: Math.random() * 6 });
587:         drops.push(stone.name);
588:       }
589:     }
590:     // region material
591:     if (Math.random() < CONFIG.drops.materialChance || boss) {
592:       const mat = this.world.region.material;
593:       const count = boss ? 2 : 1;
594:       for (let i = 0; i < count; i++) {
595:         this.groundLoot.push({
596:           lid: uid('loot'), x: enemy.x + (Math.random() - 0.5) * 1.1, y: enemy.y + (Math.random() - 0.5) * 1.1,
597:           item: { uid: uid('mat'), kind: 'material', materialId: mat.id, name: mat.name, icon: mat.icon, count: 1 },
598:           kind: 'material', expires: Date.now() + 120000, bob: Math.random() * 6
599:         });
600:       }
601:       drops.push(`${mat.name} ×${count}`);
602:     }
603:     // boss core (legendary crafting)
604:     if (boss) {
605:       this.groundLoot.push({
606:         lid: uid('loot'), x: enemy.x, y: enemy.y + 0.5,
607:         item: { uid: uid('mat'), kind: 'material', materialId: 'mat_primordial_core', name: 'Primordial Core', icon: '◉', count: 1 },
608:         kind: 'material', expires: Date.now() + 180000, bob: 0, special: true
609:       });
610:       drops.push('Primordial Core');
611:       this.sfx.play('level');
612:       Events.emit('toast', { msg: `${def.name} defeated! Boss loot dropped.`, type: 'success', duration: 5500 });
613:       if (this.currentDungeon && !this.dungeonCleared && def.id === this.currentDungeon.boss) {
614:         this.dungeonCleared = true;
615:         this.state.char.dungeons = (this.state.char.dungeons || 0) + 1;
616:         const bonus = 10000 + this.currentDungeon.level * 500;
617:         this.state.addGold(bonus, 'dungeon_clear', this.currentDungeon.name);
618:         Events.emit('toast', { msg: `Dungeon cleared: ${this.currentDungeon.name} — +${fmt(bonus)} gold!`, type: 'success', duration: 6500 });
619:         Events.emit('dungeonCleared', this.currentDungeon);
620:       }
621:     } else {
622:       Events.emit('toast', { msg: `${def.name} slain. +${fmt(rawGold)} gold, +${fmt(enemy.xp)} XP`, type: 'combat', duration: 2200, small: true });
623:     }
624:     Events.emit('kill', { enemy, drops });
625:     if (this.target === enemy) this.target = null;
626:   }
