628:   updateLoot(dt) {
629:     const now = Date.now();
630:     const stats = this.state.stats();
631:     for (const loot of [...this.groundLoot]) {
632:       loot.bob = (loot.bob || 0) + dt * 3;
633:       if (now > loot.expires) {
634:         this.groundLoot = this.groundLoot.filter(l => l !== loot);
635:         continue;
636:       }
637:       const d = Math.hypot(loot.x - this.player.x, loot.y - this.player.y);
638:       if (d < 4.2) {
639:         // magnet
640:         const sp = 3.6 * dt;
641:         if (d > 0.2) {
642:           loot.x += (this.player.x - loot.x) / d * sp;
643:           loot.y += (this.player.y - loot.y) / d * sp;
644:         }
645:       }
646:       if (d < 0.7) this.pickupLoot(loot);
647:     }
648:   }
