650:   pickupLoot(loot) {
651:     if (this.groundLoot.indexOf(loot) < 0) return;
652:     const item = loot.item;
653:     if (item.kind === 'material') {
654:       if (!this.state.hasInventorySpace()) { this.inventoryFullToast(); return; }
655:       this.state.addMaterial(item.materialId, item.count || 1);
656:       Events.emit('toast', { msg: `+${item.icon || ''} ${item.name} ×${item.count || 1}`, type: 'loot', small: true, duration: 1800 });
657:       this.sfx.play('loot');
658:     } else if (item.kind === 'stone') {
659:       if (!this.state.hasInventorySpace()) { this.inventoryFullToast(); return; }
660:       this.state.addStone(item);
661:       Events.emit('toast', { msg: `${item.icon} ${item.name}`, type: 'loot', small: true, duration: 2000 });
662:       this.sfx.play('loot');
663:     } else {
664:       if (!this.state.hasInventorySpace()) { this.inventoryFullToast(); return; }
665:       this.state.addItem(item);
666:       const rarity = RARITIES[item.rarity];
667:       Events.emit('toast', { msg: `${rarity.name} T${item.tier}: ${item.name}`, type: 'loot', color: rarity.color, duration: 2400 });
668:       this.sfx.play('loot');
669:     }
670:     this.groundLoot = this.groundLoot.filter(l => l !== loot);
671:   }
