776:   travelTo(regionId, opts = {}) {
777:     if (this.transitioning) return false;
778:     if (!REGIONS[regionId]) return false;
779:     const from = this.currentDungeon ? this.currentDungeon.region : this.state.char.region;
780:     if (regionId === from && !this.currentDungeon && opts.force !== true) {
781:       // fast travel within the same region: still costs the same-region fee
782:     }
783:     const cost = this.teleportCostTo(regionId, opts.dungeonId);
784:     if (cost > 0 && !this.state.spendGold(cost, 'teleport', `${regionId}${opts.dungeonId ? ':' + opts.dungeonId : ''}`)) {
785:       Events.emit('toast', { msg: `Not enough gold. Teleport costs ${fmt(cost)}.`, type: 'warn' });
786:       this.sfx.play('error');
787:       return false;
788:     }
789:     if (cost > 0) {
790:       Events.emit('toast', { msg: `Teleported for ${fmt(cost)} gold.`, type: 'info', small: true });
791:     }
792:     this.enterRegion(regionId, { dungeonId: opts.dungeonId, initial: false });
793:     return true;
794:   }
795: 
796:   enterDungeon(dungeonId) {
797:     const d = DUNGEONS.find(x => x.id === dungeonId);
798:     if (!d) return false;
799:     if (this.state.char.level + 3 < d.level) {
800:       Events.emit('toast', { msg: `Recommended level ${d.level}. You can still enter, but be careful.`, type: 'warn' });
801:     }
802:     return this.travelTo(d.region, { dungeonId: d.id });
803:   }
