885:   bindInput() {
886:     window.addEventListener('keydown', (e) => {
887:       if (e.target && ['INPUT', 'TEXTAREA', 'SELECT'].includes(e.target.tagName)) return;
888:       const k = e.key.toLowerCase();
889:       if (['w', 'arrowup'].includes(k)) { this.input.up = true; e.preventDefault(); }
890:       else if (['s', 'arrowdown'].includes(k)) { this.input.down = true; e.preventDefault(); }
891:       else if (['a', 'arrowleft'].includes(k)) { this.input.left = true; e.preventDefault(); }
892:       else if (['d', 'arrowright'].includes(k)) { this.input.right = true; e.preventDefault(); }
893:       else if (k === ' ') { this.attackPressed(); e.preventDefault(); }
894:       else if (k === 'q') { this.skillPressed(); e.preventDefault(); }
895:       else if (k === 'e') { this.interactPressed(); e.preventDefault(); }
896:       else if (k === 'h') { this.useHealthPotion(); e.preventDefault(); }
897:       else if (k === 'j') { this.useManaPotion(); e.preventDefault(); }
898:       else if (k === 'm') { Events.emit('openMap'); }
899:       else if (k === 'b') { Events.emit('openBag'); }
900:       else if (k === 'c') { Events.emit('openCharacter'); }
901:       else if (k === 'r') { this.toggleMount(); }
902:       else if (k === 'f') { this.toggleAutoAttack(); }
903:     });
904:     window.addEventListener('keyup', (e) => {
905:       const k = e.key.toLowerCase();
906:       if (['w', 'arrowup'].includes(k)) this.input.up = false;
907:       if (['s', 'arrowdown'].includes(k)) this.input.down = false;
908:       if (['a', 'arrowleft'].includes(k)) this.input.left = false;
909:       if (['d', 'arrowright'].includes(k)) this.input.right = false;
910:     });
911:     window.addEventListener('blur', () => {
912:       this.input.up = this.input.down = this.input.left = this.input.right = false;
913:       this.setJoystick(0, 0);
914:     });
915: 
916:     const canvas = this.canvas;
917:     canvas.addEventListener('pointerdown', (e) => {
918:       if (this.transitioning || this.player.dead) return;
919:       this.sfx.init();
920:       this.sfx.resume();
921:       const rect = canvas.getBoundingClientRect();
922:       const x = e.clientX - rect.left;
923:       const y = e.clientY - rect.top;
924:       this.handleTap(x, y);
925:     });
926:     canvas.addEventListener('contextmenu', e => e.preventDefault());
927:   }
