621:   // ---------- items helpers ----------
622:   rarityColor(item) { return RARITIES[item.rarity]?.color || 'var(--text)'; }
623:   itemIcon(item) {
624:     if (item.kind === 'material') return item.icon || MATERIALS[item.materialId]?.icon || '📦';
625:     if (item.kind === 'stone') return item.icon || '◈';
626:     return SLOTS.find(s => s.id === item.slot)?.icon || '🗡';
627:   }
628:   itemRestriction(item) {
629:     if (!item || item.kind !== 'equip') return '';
630:     return `${CLASSES[item.classId].name} · ${FACTIONS[item.faction].name}`;
631:   }
632:   statName(k) {
633:     return { str: 'Strength', int: 'Intelligence', dex: 'Dexterity', vit: 'Vitality', atk: 'Attack', def: 'Defense', crit: 'Crit' }[k] || k;
634:   }
635:   itemStatsHtml(item) {
636:     if (!item?.stats) return '';
637:     const rows = [];
638:     for (const k of ['atk', 'def', 'str', 'int', 'dex', 'vit']) {
639:       if (item.stats[k]) rows.push(`<div class="stat-line"><span>${this.statName(k)}</span><b class="pos">+${item.stats[k]}</b></div>`);
640:     }
641:     if (item.stats.crit) rows.push(`<div class="stat-line"><span>Critical Chance</span><b class="pos">+${pct(item.stats.crit, 2)}</b></div>`);
642:     for (const b of item.bonuses || []) {
643:       const stat = BONUS_STATS[b.stat];
644:       rows.push(`<div class="stat-line"><span>${stat.icon} ${stat.name} (bonus)</span><b class="pos">+${b.value}${b.stat === 'crit' ? '%' : ''}</b></div>`);
645:     }
646:     return rows.join('');
647:   }
648:   itemCard(item, actions = '') {
649:     const color = this.rarityColor(item);
650:     const meta = item.kind === 'material'
651:       ? `Material ×${item.count}`
652:       : item.kind === 'stone'
653:         ? `${CLASSES[item.classId].name} · ${BONUS_STATS[item.stat].name} +${item.value}${item.stat === 'crit' ? '%' : ''}`
654:         : `${SLOT_NAME[item.slot]} · ${RARITIES[item.rarity].name} · T${item.tier}`;
655:     return `
656:       <button class="item-card" style="--rar:${color}" data-act="item-detail" data-uid="${item.uid}">
657:         <div class="itop"><span class="iicon">${this.itemIcon(item)}</span>${item.kind === 'equip' ? `<span class="tier-badge">T${item.tier}</span>` : ''}</div>
658:         <span class="iname">${escapeHtml(item.name)}</span>
659:         <span class="imeta">${meta}</span>
660:         ${item.kind === 'equip' && this.itemRestriction(item) !== `${CLASSES[this.state.char.classId].name} · ${FACTIONS[this.state.char.faction].name}` ? `<span class="restrict">${this.itemRestriction(item)}</span>` : ''}
661:         ${actions}
662:       </button>`;
663:   }
664: 
665:   itemDetailHtml(uid, opts = {}) {
666:     const item = this.state.findItem(uid);
667:     if (!item) return '<div class="empty"><span>?</span>That item is no longer here.</div>';
668:     const color = item.kind === 'equip' ? this.rarityColor(item) : item.kind === 'stone' ? '#ffd166' : '#a8e07a';
669:     const equippedSlot = Object.entries(this.state.data.equipped).find(([, it]) => it?.uid === uid)?.[0];
670:     const can = item.kind === 'equip' ? this.state.canEquip(item) : { ok: false };
671:     const insideInventory = this.state.data.inventory.some(i => i.uid === uid);
672:     const insideStorage = this.state.data.storage.some(i => i.uid === uid);
673: 
674:     let body = '';
675:     if (item.kind === 'equip') {
676:       body = `
677:         <div class="stat-grid mt8">${this.itemStatsHtml(item)}</div>
678:         <div class="row wrap mt8">
679:           <span class="tag">${SLOT_NAME[item.slot]}</span>
680:           <span class="tag">${RARITIES[item.rarity].name}</span>
681:           <span class="tag gold">Tier ${item.tier}</span>
682:           <span class="tag">Item level ${item.level}</span>
683:           <span class="tag ${can.ok ? 'green' : 'red'}">${this.itemRestriction(item)} only</span>
684:         </div>
685:         ${item.bonuses?.length ? `<div class="row wrap mt8">${item.bonuses.map(b => `<span class="tag green">${BONUS_STATS[b.stat].icon} +${b.value}${b.stat === 'crit' ? '%' : ''}</span>`).join('')}</div>` : ''}
686:         <div class="row wrap mt12">
687:           ${equippedSlot
688:             ? `<button class="btn btn-sm" data-act="unequip" data-slot="${equippedSlot}">Unequip</button>`
689:             : insideInventory && can.ok
690:               ? `<button class="btn btn-sm btn-primary" data-act="equip" data-uid="${uid}">Equip</button>`
691:               : insideInventory
692:                 ? `<button class="btn btn-sm" disabled>Cannot equip</button>` : ''}
693:           ${insideInventory ? `<button class="btn btn-sm" data-act="sell" data-uid="${uid}">Sell · ${fmt(Math.round((item.value || 100) * CONFIG.economy.npcSellRate))}g</button>` : ''}
694:           ${insideInventory ? `<button class="btn btn-sm" data-act="deposit" data-uid="${uid}">Store</button>` : ''}
695:           ${insideStorage ? `<button class="btn btn-sm btn-primary" data-act="withdraw" data-uid="${uid}">Withdraw</button>` : ''}
696:           <button class="btn btn-sm btn-ghost" data-act="item-back">← Back</button>
697:         </div>
698:         ${!equippedSlot && insideInventory && !can.ok ? `<div class="note warn mt8">Class and faction restrictions are strict. Everyone can farm, craft, buy and sell this item — only a matching ${CLASSES[item.classId].name} of the ${FACTIONS[item.faction].name} can wear it.</div>` : ''}
699:         <div class="note mt8">Rarity visuals: Common/Grey are understated, Green/Blue improve, Epic and above grow increasingly spectacular. Tier glow: T3 none, T2 small, T1 strong. Effects show on your character.</div>`;
700:     } else if (item.kind === 'stone') {
701:       body = `
702:         <div class="stat-grid mt8">
703:           <div class="stat-line"><span>${BONUS_STATS[item.stat].name}</span><b class="pos">+${item.value}${item.stat === 'crit' ? '%' : ''}</b></div>
704:           <div class="stat-line"><span>Class</span><b>${CLASSES[item.classId].name}</b></div>
705:           <div class="stat-line"><span>Stone tier</span><b>${item.tier === 3 ? 'Sovereign' : item.tier === 2 ? 'Greater' : 'Lesser'}</b></div>
706:         </div>
707:         <p class="panel-lead mt8">Boss stones are tradeable. Apply up to 3 per equipment piece at the Enchanter. Replacing a bonus returns the old stone — nothing is destroyed.</p>
708:         <div class="row wrap mt8">
