1227:   panelEconomy() {
1228:     const eco = this.state.economySummary();
1229:     const sourceTotal = Math.max(1, eco.totalIn);
1230:     const sinkTotal = Math.max(1, eco.totalOut);
1231:     const sources = Object.entries(eco.sources).sort((a, b) => b[1] - a[1]);
1232:     const sinks = Object.entries(eco.sinks).sort((a, b) => b[1] - a[1]);
1233:     return `
1234:       <div class="panel-grid grid-3">
1235:         <div class="big-stat"><b>${fmt(eco.goldPerHour)}</b><span>Gold / hour</span></div>
1236:         <div class="big-stat"><b>${fmt(eco.lifetimeEarned)}</b><span>Lifetime in</span></div>
1237:         <div class="big-stat"><b>${fmt(eco.lifetimeSpent)}</b><span>Lifetime out</span></div>
1238:       </div>
1239:       <div class="row between mt8"><span class="tiny muted">Target endgame income: <b>${fmt(eco.target)} gold/hour</b></span><span class="tiny muted">Net: ${fmt(eco.net)}</span></div>
1240:       <div class="section-title">Gold sources (in)</div>
1241:       <div class="eco-bars">${sources.length ? sources.map(([k, v]) => `<div class="eco-bar"><span>${this.labelize(k)}</span><div class="track"><div style="width:${v / sourceTotal * 100}%"></div></div><b>${fmt(v)}</b></div>`).join('') : '<div class="tiny muted">No income yet.</div>'}</div>
1242:       <div class="section-title">Gold sinks (out)</div>
1243:       <div class="eco-bars">${sinks.length ? sinks.map(([k, v]) => `<div class="eco-bar out"><span>${this.labelize(k)}</span><div class="track"><div style="width:${v / sinkTotal * 100}%"></div></div><b>${fmt(v)}</b></div>`).join('') : '<div class="tiny muted">No spending yet.</div>'}</div>
1244:       <div class="section-title">Recent ledger</div>
1245:       <div class="ledger">${eco.history.length ? eco.history.map(h => `<div class="ledger-line"><span>${timeAgo(h.ts)} · ${this.labelize(h.category)}</span><span class="${h.type === 'in' ? 'in' : 'out'}">${h.type === 'in' ? '+' : '−'}${fmt(h.amount)}g</span></div>`).join('') : '<div class="tiny muted">No transactions.</div>'}</div>
1246:       <div class="note mt8">Playtime: ${fmtTime(this.state.data.playtime)}. All gold changes flow through a single ledger. Player trades only transfer existing gold. NPC sales are a gold source; fusion, teleports, potions, stalls and enchants are sinks.</div>
1247:     `;
1248:   }
