202:     if (type !== 'path' && type !== 'plaza' && type !== 'plaza_light' && t.variant % 11 === 0) {
203:       ctx.fillStyle = shade(base, 0.14);
204:       ctx.fillRect(cx - 2, cy - 3, 1, 3);
205:       ctx.fillRect(cx + 2, cy + 1, 1, 2);
206:     }
207:     if (type === 'path' || type === 'plaza') {
208:       // cobble hints
209:       if (t.variant % 4 === 0) {
210:         ctx.fillStyle = shade(base, 0.09);
211:         ctx.fillRect(cx - 5, cy - 2, 5, 1);
212:         ctx.fillRect(cx + 2, cy + 2, 4, 1);
213:         ctx.fillStyle = shade(base, -0.07);
214:         ctx.fillRect(cx - 2, cy + 3, 6, 1);
215:       }
216:     }
217:   }
218: 
219:   // ------------------------------------------------------------
220:   // WEATHER
221:   // ------------------------------------------------------------
222:   makeWeather(kind) {
223:     const n = WEATHER_COUNT[kind] || 24;
224:     this.particles = [];
225:     for (let i = 0; i < n; i++) {
226:       this.particles.push({
227:         x: Math.random() * this.width,
228:         y: Math.random() * this.height,
229:         vx: (Math.random() - 0.5) * 12,
230:         vy: 8 + Math.random() * 26,
231:         size: 1 + Math.random() * 2,
232:         phase: Math.random() * Math.PI * 2,
233:         speed: 0.4 + Math.random() * 1.6,
234:         alpha: 0.25 + Math.random() * 0.5
235:       });
236:     }
237:     this.weatherKind = kind;
238:   }
239: 
240:   updateWeather(dt) {
241:     const kind = this.weatherKind;
242:     for (const p of this.particles) {
243:       p.phase += dt * p.speed;
244:       if (kind === 'embers') {
245:         p.y -= (14 + p.speed * 22) * dt;
246:         p.x += Math.sin(p.phase * 2) * 14 * dt;
247:       } else if (kind === 'snow') {
248:         p.y += p.vy * dt;
249:         p.x += Math.sin(p.phase) * 16 * dt;
250:       } else if (kind === 'sand') {
251:         p.x += (40 + p.speed * 45) * dt;
252:         p.y += Math.sin(p.phase) * 8 * dt;
253:       } else if (kind === 'stars') {
254:         // static twinkle
255:       } else if (kind === 'mist') {
256:         p.x += (4 + p.speed * 4) * dt;
257:         p.y += Math.sin(p.phase) * 2 * dt;
258:       } else {
259:         p.y += p.vy * dt * 0.7;
260:         p.x += Math.sin(p.phase * 1.4) * 20 * dt;
261:       }
262:       if (p.y > this.height + 20) { p.y = -20; p.x = Math.random() * this.width; }
263:       if (p.y < -30) { p.y = this.height + 10; p.x = Math.random() * this.width; }
264:       if (p.x > this.width + 20) p.x = -20;
265:       if (p.x < -20) p.x = this.width + 20;
266:     }
267:   }
268: 
269:   drawWeather(ctx) {
270:     const kind = this.weatherKind;
271:     const pal = this.world.region.palette;
272:     ctx.save();
273:     if (kind === 'leaves') {
274:       for (const p of this.particles) {
275:         ctx.globalAlpha = p.alpha;
276:         ctx.fillStyle = Math.sin(p.phase) > 0 ? pal.accent : '#d5a44c';
277:         ctx.fillRect(p.x, p.y, p.size + 1, p.size);
278:       }
279:     } else if (kind === 'embers') {
280:       for (const p of this.particles) {
281:         ctx.globalAlpha = p.alpha * (0.7 + Math.sin(p.phase * 2) * 0.3);
282:         ctx.fillStyle = Math.sin(p.phase) > 0 ? '#ffb23e' : '#ff5a3c';
283:         ctx.fillRect(p.x, p.y, p.size, p.size);
284:       }
285:     } else if (kind === 'spores') {
286:       for (const p of this.particles) {
287:         ctx.globalAlpha = p.alpha * (0.5 + Math.sin(p.phase) * 0.5);
288:         ctx.fillStyle = '#c9a0ff';
289:         ctx.fillRect(p.x, p.y, p.size, p.size);
290:         ctx.globalAlpha *= 0.4;
291:         ctx.fillRect(p.x - 1, p.y - 1, p.size + 2, p.size + 2);
292:       }
293:     } else if (kind === 'snow') {
294:       for (const p of this.particles) {
295:         ctx.globalAlpha = p.alpha;
296:         ctx.fillStyle = '#f2fbff';
297:         ctx.fillRect(p.x, p.y, p.size, p.size);
298:       }
299:     } else if (kind === 'sand') {
300:       for (const p of this.particles) {
301:         ctx.globalAlpha = p.alpha * 0.6;
302:         ctx.fillStyle = '#f0d79a';
303:         ctx.fillRect(p.x, p.y, p.size + 2, 1);
304:       }
305:     } else if (kind === 'stars') {
306:       for (const p of this.particles) {
307:         ctx.globalAlpha = 0.25 + Math.abs(Math.sin(p.phase)) * 0.6;
308:         ctx.fillStyle = Math.sin(p.phase * 2) > 0 ? '#fff4c4' : '#c9b4ff';
309:         ctx.fillRect(p.x, p.y, p.size, p.size);
310:       }
311:     } else if (kind === 'mist') {
312:       for (const p of this.particles) {
313:         ctx.globalAlpha = 0.05 + p.alpha * 0.05;
314:         ctx.fillStyle = '#b7d4ea';
315:         ctx.beginPath();
316:         ctx.ellipse(p.x, p.y, 90 + p.size * 25, 22 + p.size * 5, 0, 0, Math.PI * 2);
317:         ctx.fill();
318:       }
319:     }
320:     ctx.restore();
321:   }
322: 
323:   // ------------------------------------------------------------
324:   // MAIN RENDER
325:   // ------------------------------------------------------------
326:   render(game, dt) {
327:     const ctx = this.ctx;
328:     this.time += dt;
329:     this.updateWeather(dt);
330:     const world = this.world;
331:     if (!world || !game.player) return;
332: 
333:     // camera follow
334:     const p = this.iso(game.player.x, game.player.y);
335:     this.camTarget.x = lerp(this.camTarget.x, p.x - this.width / 2, 0.18);
336:     this.camTarget.y = lerp(this.camTarget.y, p.y - this.height / 2 - 34, 0.18);
337:     this.clampCamera(this.camTarget);
338:     this.cam.x = lerp(this.cam.x, this.camTarget.x, 0.22);
339:     this.cam.y = lerp(this.cam.y, this.camTarget.y, 0.22);
340:     if (Math.abs(this.cam.x - this.camTarget.x) < 0.05) this.cam.x = this.camTarget.x;
341:     if (Math.abs(this.cam.y - this.camTarget.y) < 0.05) this.cam.y = this.camTarget.y;
342: 
343:     ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
344:     ctx.imageSmoothingEnabled = false;
345:     const pal = world.region.palette;
346:     const bg = ctx.createLinearGradient(0, 0, 0, this.height);
347:     bg.addColorStop(0, pal.sky);
348:     bg.addColorStop(1, shade(pal.sky, -0.12));
349:     ctx.fillStyle = bg;
350:     ctx.fillRect(0, 0, this.width, this.height);
351: 
352:     // ground
353:     ctx.drawImage(this.ground, -Math.round(this.cam.x), -Math.round(this.cam.y));
354: 
355:     this.drawWaterFX(ctx);
356: 
357:     // lights beneath objects
358:     this.drawGroundLights(ctx, world);
359: 
360:     // collect drawables
361:     const drawables = [];
362:     const margin = 220;
363:     const visible = (sx, sy) => sx > -margin && sx < this.width + margin && sy > -margin - 100 && sy < this.height + margin;
364: 
365:     for (const prop of world.props) {
366:       const s = this.worldToScreen(prop.x, prop.y);
367:       if (visible(s.x, s.y - 80)) drawables.push({ z: prop.x + prop.y, read: () => this.drawPropSprite(ctx, prop, s) });
368:     }
369:     for (const node of world.nodes) {
370:       if (node.respawnAt > Date.now()) continue;
371:       const s = this.worldToScreen(node.x, node.y);
372:       if (visible(s.x, s.y)) drawables.push({ z: node.x + node.y, read: () => this.drawNodeSprite(ctx, node, s) });
373:     }
374:     for (const h of world.hidden) {
375:       if (h.opened) continue;
376:       const s = this.worldToScreen(h.x, h.y);
377:       if (visible(s.x, s.y)) drawables.push({ z: h.x + h.y, read: () => this.drawChestSprite(ctx, h, s) });
378:     }
379:     for (const npc of world.npcs) {
380:       const s = this.worldToScreen(npc.x, npc.y);
381:       if (visible(s.x, s.y)) drawables.push({ z: npc.x + npc.y, read: () => this.drawNpcSprite(ctx, npc, s, game) });
382:     }
383:     for (const enemy of world.enemies) {
384:       if (!enemy.alive) continue;
385:       const s = this.worldToScreen(enemy.x, enemy.y);
386:       if (visible(s.x, s.y)) drawables.push({ z: enemy.x + enemy.y + 0.01, read: () => this.drawEnemySprite(ctx, enemy, s, game) });
387:     }
388:     if (game.groundLoot) {
389:       for (const loot of game.groundLoot) {
390:         const s = this.worldToScreen(loot.x, loot.y);
391:         if (visible(s.x, s.y)) drawables.push({ z: loot.x + loot.y + 0.005, read: () => this.drawLootSprite(ctx, loot, s) });
392:       }
393:     }
394:     // player
395:     const ps = this.worldToScreen(game.player.x, game.player.y);
396:     drawables.push({ z: game.player.x + game.player.y + 0.02, read: () => this.drawPlayerSprite(ctx, game, ps) });
397: 
398:     drawables.sort((a, b) => a.z - b.z);
399:     for (const d of drawables) d.read();
400: 
401:     // target ring under current target
402:     if (game.target && game.target.alive) this.drawTargetRing(ctx, game.target);
403:     if (game.interactTarget) this.drawInteractRing(ctx, game.interactTarget);
404: 
405:     // pets (drawn above world)
406:     if (game.state.char.petActive && game.state.petDef()) {
407:       const off = this.iso(game.player.x, game.player.y);
408:       ctx.save();
409:       const S = this.spriteScale();
410:       ctx.translate(ps.x + 28, ps.y - 20);
411:       ctx.scale(S * 0.8, S * 0.8);
412:       drawPet(ctx, game.state.petDef(), this.time);
413:       ctx.restore();
414:     }
415: 
416:     // skill / combat effects and projectiles
417:     this.drawEffects(ctx, game);
418: 
419:     // weather
420:     this.drawWeather(ctx);
421: 
422:     // ambient fog / region tint
423:     ctx.save();
424:     const fog = ctx.createRadialGradient(this.width / 2, this.height / 2, Math.min(this.width, this.height) * 0.18, this.width / 2, this.height / 2, Math.max(this.width, this.height) * 0.78);
425:     fog.addColorStop(0, pal.fog);
426:     fog.addColorStop(1, 'rgba(5,4,10,0.42)');
427:     ctx.fillStyle = fog;
428:     ctx.fillRect(0, 0, this.width, this.height);
429:     ctx.restore();
430: 
431:     if (world.mode === 'dungeon') {
432:       ctx.fillStyle = 'rgba(8,4,14,0.16)';
433:       ctx.fillRect(0, 0, this.width, this.height);
434:     }
435: 
436:     // minimap occasionally
437:     const now = performance.now();
438:     if (this.minimapCanvas && now - this.lastMinimap > 220) {
439:       this.lastMinimap = now;
440:       this.drawMinimap(this.minimapCanvas, game);
441:     }
442:   }
443: 
444:   spriteScale() {
445:     const base = Math.min(this.width, this.height) < 620 ? 2.0 : 2.35;
446:     return base;
447:   }
448: 
449:   // ------------------------------------------------------------
450:   // OBJECT RENDERING
451:   // ------------------------------------------------------------
452:   drawShadow(ctx, sx, sy, w, alpha = 0.28) {
453:     ctx.save();
454:     ctx.globalAlpha = alpha;
455:     ctx.fillStyle = '#08060d';
456:     ctx.beginPath();
457:     ctx.ellipse(sx, sy + 2, w, w * 0.4, 0, 0, Math.PI * 2);
458:     ctx.fill();
459:     ctx.restore();
460:   }
461: 
462:   drawPropSprite(ctx, prop, s) {
463:     const S = this.spriteScale() * (prop.scale || 1);
464:     const sc = this.spriteScale();
465:     const shadowW = prop.type === 'house' ? 36 : prop.type === 'tent' ? 26 : prop.kind === 'tree' ? 20 : 12;
466:     this.drawShadow(ctx, s.x, s.y, shadowW * sc * 0.55, prop.type === 'house' ? 0.35 : 0.22);
467:     ctx.save();
468:     ctx.translate(s.x, s.y);
469:     ctx.scale(S, S);
470:     drawProp(ctx, { ...prop, scale: 1 }, this.time, this.biomeStyle());
471:     ctx.restore();
472: 
473:     // prop light sources
474:     if (['campfire', 'brazier', 'forge', 'crystal', 'void_crystal', 'star_well', 'lava_rock'].includes(prop.kind)) {
475:       this.addLight(ctx, s.x, s.y - 12 * sc, prop.kind === 'forge' ? 120 : 80, prop.kind === 'crystal' || prop.kind === 'void_crystal' ? '#8fe2ff' : '#ff8a3c');
476:     }
477:   }
478: 
479:   drawNodeSprite(ctx, node, s) {
480:     const S = this.spriteScale();
481:     this.drawShadow(ctx, s.x, s.y, 12, 0.2);
482:     ctx.save();
483:     ctx.translate(s.x, s.y);
484:     ctx.scale(S, S);
485:     drawProp(ctx, { ...node, kind: 'node', scale: node.scale || 1 }, this.time, this.biomeStyle());
486:     ctx.restore();
487:     this.addLight(ctx, s.x, s.y - 10, 45, '#b6ff9a', 0.25);
488:     // sparkle
489:     const t = this.time * 2 + node.x;
490:     ctx.save();
491:     ctx.globalAlpha = 0.5 + Math.sin(t) * 0.3;
492:     ctx.fillStyle = '#e8ffcc';
493:     ctx.fillRect(s.x + Math.sin(t * 1.7) * 12, s.y - 24 + Math.cos(t * 1.3) * 6, 2, 2);
494:     ctx.restore();
495:   }
496: 
497:   drawLootSprite(ctx, loot, s) {
498:     const item = loot.item;
499:     const isStone = item.kind === 'stone';
500:     const isMat = item.kind === 'material';
501:     const color = isStone ? '#ffd166' : isMat ? '#a8e07a' : (RARITIES[item.rarity]?.color || '#ffffff');
502:     const bob = Math.sin(this.time * 4 + (loot.bob || 0)) * 3;
503:     const x = s.x;
504:     const y = s.y + bob;
505:     ctx.save();
506:     // pickup beam
507:     ctx.globalAlpha = 0.18 + Math.sin(this.time * 5 + (loot.bob || 0)) * 0.06;
508:     const g = ctx.createLinearGradient(x, y - 50, x, y);
509:     g.addColorStop(0, 'rgba(255,255,255,0)');
510:     g.addColorStop(1, this.hexAlpha(color, 0.6));
511:     ctx.fillStyle = g;
512:     ctx.fillRect(x - 4, y - 50, 8, 50);
513:     ctx.globalAlpha = 1;
514:     // glow
515:     this.addLight(ctx, x, y - 10, 28, color, 0.18);
516:     // pouch / gem
517:     if (isMat) {
518:       ctx.fillStyle = '#3f4a32';
519:       ctx.fillRect(x - 5, y - 11, 10, 9);
520:       ctx.fillStyle = color;
521:       ctx.fillRect(x - 3, y - 13, 6, 5);
522:       ctx.fillStyle = '#e8ffd0';
523:       ctx.fillRect(x - 1, y - 12, 2, 2);
524:     } else if (isStone) {
525:       ctx.fillStyle = '#2b2130';
526:       ctx.fillRect(x - 5, y - 10, 10, 8);
527:       ctx.fillStyle = color;
528:       ctx.fillRect(x - 3, y - 13, 6, 6);
529:       ctx.fillStyle = '#fff6d0';
530:       ctx.fillRect(x - 1, y - 12, 2, 2);
531:     } else {
532:       ctx.fillStyle = '#2b2130';
533:       ctx.fillRect(x - 6, y - 11, 12, 9);
534:       ctx.fillStyle = this.hexAlpha(color, 0.9);
535:       ctx.fillRect(x - 4, y - 12, 8, 3);
536:       ctx.fillStyle = '#4a3a2a';
537:       ctx.fillRect(x - 6, y - 4, 12, 2);
538:       ctx.fillStyle = color;
539:       ctx.fillRect(x - 1, y - 8, 2, 2);
540:     }
541:     // sparkle
542:     ctx.globalAlpha = 0.6 + Math.sin(this.time * 6 + (loot.bob || 0)) * 0.4;
543:     ctx.fillStyle = '#fff8d8';
544:     ctx.fillRect(x + 8, y - 20, 2, 2);
545:     ctx.fillRect(x - 10, y - 15, 1, 1);
546:     ctx.restore();
547:   }
548: 
549:   drawChestSprite(ctx, h, s) {    const S = this.spriteScale();
550:     this.drawShadow(ctx, s.x, s.y, 12, 0.22);
551:     ctx.save();
552:     ctx.translate(s.x, s.y);
553:     ctx.scale(S, S);
554:     drawProp(ctx, { ...h, type: 'chest', kind: 'chest', scale: 1 }, this.time, this.biomeStyle());
555:     ctx.restore();
556:     this.addLight(ctx, s.x, s.y - 10, 55, '#ffdf37', 0.28);
557:     const t = this.time * 2.4 + h.x;
558:     ctx.save();
559:     ctx.globalAlpha = 0.6 + Math.sin(t) * 0.3;
560:     ctx.fillStyle = '#fff3a8';
561:     ctx.fillRect(s.x - 10 + Math.sin(t) * 3, s.y - 34 + Math.cos(t * 1.3) * 4, 2, 2);
562:     ctx.fillRect(s.x + 8 + Math.cos(t) * 3, s.y - 28 + Math.sin(t * 1.7) * 4, 2, 2);
563:     ctx.restore();
564:   }
565: 
566:   drawNpcSprite(ctx, npc, s, game) {
567:     const S = this.spriteScale();
568:     this.drawShadow(ctx, s.x, s.y, 10, 0.24);
569:     ctx.save();
570:     ctx.translate(s.x, s.y);
571:     ctx.scale(S, S);
572:     drawNpc(ctx, npc, this.time);
573:     ctx.restore();
574: 
575:     // name and role
576:     if (game.state.data.settings.showNames) {
577:       this.drawWorldLabel(ctx, npc.name, s.x, s.y - 104, '#f0d89a', 10);
578:     }
579:     const state = game.state;
580:     let marker = null;
581:     if (npc.role === 'Quest Keeper') {
582:       const available = state.availableQuests().some(q => q.region === npc.region);
583:       const complete = state.data.quests.active.some(a => {
584:         const q = game.questDef(a.id);
585:         return q && q.region === npc.region && state.isQuestComplete(q);
586:       });
587:       if (available) marker = '!';
588:       else if (complete) marker = '?';
589:     }
590:     if (marker) {
591:       const y = s.y - 126 + Math.sin(this.time * 2.5) * 3;
592:       ctx.save();
593:       ctx.font = 'bold 22px Georgia, serif';
594:       ctx.textAlign = 'center';
595:       ctx.lineWidth = 4;
596:       ctx.strokeStyle = 'rgba(12,8,18,0.9)';
597:       ctx.strokeText(marker, s.x, y);
598:       ctx.fillStyle = marker === '!' ? '#ffd15c' : '#7dffc1';
599:       ctx.fillText(marker, s.x, y);
600:       ctx.restore();
601:     }
602:   }
603: 
604:   drawEnemySprite(ctx, enemy, s, game) {
605:     const S = this.spriteScale();
606:     const def = enemy.def;
607:     const shadowW = def.boss ? 30 : enemy.elite ? 16 : 12;
608:     this.drawShadow(ctx, s.x, s.y, shadowW, def.boss ? 0.4 : 0.25);
609:     if (def.boss) {
610:       this.addLight(ctx, s.x, s.y - 30, 140, def.color, 0.18);
611:       // boss aura ring
612:       ctx.save();
613:       ctx.globalAlpha = 0.25 + Math.sin(this.time * 2) * 0.08;
614:       ctx.strokeStyle = def.color;
615:       ctx.lineWidth = 2;
616:       ctx.beginPath();
617:       ctx.ellipse(s.x, s.y, 46, 18, 0, 0, Math.PI * 2);
618:       ctx.stroke();
619:       ctx.restore();
620:     }
621:     if (enemy.elite) this.addLight(ctx, s.x, s.y - 20, 50, '#ffd166', 0.16);
622:     ctx.save();
623:     ctx.translate(s.x, s.y);
624:     ctx.scale(S, S);
625:     drawEnemy(ctx, enemy, this.time);
626:     ctx.restore();
627: 
628:     // hp bar
629:     const w = def.boss ? 92 : enemy.elite ? 56 : 40;
630:     const y = s.y - (def.boss ? 120 : enemy.elite ? 92 : 74) * (enemy.scale || 1) / 1.2;
631:     this.drawBar(ctx, s.x - w / 2, y, w, 4, enemy.hp / enemy.maxHp, def.boss ? '#ff5a5a' : enemy.elite ? '#ffd166' : '#65d67a');
632:     if (game.state.data.settings.showNames) {
633:       const nm = (enemy.elite ? 'Elite ' : '') + def.name + (def.boss ? '  ☠' : '');
634:       this.drawWorldLabel(ctx, nm, s.x, y - 5, def.boss ? '#ffb08a' : enemy.elite ? '#ffd166' : '#e6e2d8', def.boss ? 11 : 9);
635:     }
636:   }
637: 
638:   drawPlayerSprite(ctx, game, s) {
639:     const state = game.state;
640:     const c = state.char;
641:     const S = this.spriteScale();
642:     const eq = state.data.equipped;
643:     const wings = state.wingsDef();
644:     const mount = state.mountDef();
645:     const cosmetic = state.costumePalette();
646: 
647:     // equipment aura
648:     const aura = this.equipmentAura(state);
649:     if (aura) {
650:       this.addLight(ctx, s.x, s.y - 45, 80 + aura.strength * 20, aura.color, 0.13 + aura.strength * 0.05);
651:       ctx.save();
652:       ctx.globalAlpha = 0.25 + aura.strength * 0.08;
653:       ctx.strokeStyle = aura.color;
654:       ctx.lineWidth = 1.5;
655:       ctx.beginPath();
656:       ctx.ellipse(s.x, s.y, 26 + aura.strength * 5, 10 + aura.strength * 2, 0, 0, Math.PI * 2);
657:       ctx.stroke();
658:       ctx.restore();
659:     }
660:     this.drawShadow(ctx, s.x, s.y, mount ? 24 : 13, mount ? 0.32 : 0.26);
661: 
662:     ctx.save();
663:     ctx.translate(s.x, s.y);
664:     ctx.scale(S, S);
665:     drawCharacter(ctx, {
666:       faction: c.faction, classId: c.classId, gender: c.gender,
667:       hairStyle: c.hair, hairColor: state.hairColorHex(), eyeColor: state.eyeColorHex(),
668:       equipment: eq, wings, mount, cosmetic,
669:       time: this.time, moving: game.player.moving,
