66:   const mounted = !!o.mount;
67: 
68:   ctx.save();
69:   ctx.scale(facing, 1);
70: 
71:   // wings behind body
72:   if (o.wings) drawWings(ctx, o.wings, time, -28 + bob, demon);
73: 
74:   // mount drawn first (body sits higher)
75:   if (mounted) {
76:     drawMount(ctx, o.mount, time, moving);
77:   }
78:   const lift = mounted ? -13 : 0;
79: 
80:   ctx.save();
81:   ctx.translate(0, lift + bob);
82: 
83:   // ---- legs ----
84:   const pantsColor = eq.pants ? shade(EQUIP_COLOR(eq.pants.rarity, pal.cloth2), -0.12) : pal.cloth2;
85:   const bootColor = eq.boots ? shade(EQUIP_COLOR(eq.boots.rarity, pal.metal2), -0.05) : pal.metal2;
86:   const legSwing = Math.round(swing * 2);
87:   // back leg
88:   p(ctx, -4, -14, 4, 10 + legSwing, shade(pantsColor, -0.12));
89:   p(ctx, -5, -4 + legSwing, 5, 4, shade(bootColor, -0.12));
90:   // front leg
91:   p(ctx, 1, -14, 4, 10 - legSwing, pantsColor);
92:   p(ctx, 1, -4 - legSwing, 5, 4, bootColor);
93: 
94:   if (o.classId === 'mage') {
95:     // robe skirt over legs
96:     p(ctx, -8, -19, 16, 6, pal.cloth);
97:     p(ctx, -9, -14, 18, 7, pal.cloth);
98:     p(ctx, -8, -7, 7, 7, shade(pal.cloth, -0.07));
99:     p(ctx, 1, -7, 7, 7, pal.cloth);
100:     p(ctx, -5, -10, 10, 1, pal.trim);
101:   }
102: 
103:   // ---- torso ----
104:   const chestRar = eq.chest?.rarity;
105:   const chestAccent = EQUIP_COLOR(chestRar, pal.metal);
106:   const chestPrimary = eq.chest ? (chestRar === 'common' || chestRar === 'grey' ? pal.metal : chestAccent) : pal.cloth;
107:   const chestDark = shade(chestPrimary, -0.18);
108:   const shoulder = female ? 7 : 9;
109: 
110:   if (o.classId === 'warrior') {
111:     p(ctx, -shoulder, -29, shoulder * 2, 14, pal.metal2);
112:     p(ctx, -shoulder + 1, -29, shoulder * 2 - 2, 12, chestPrimary);
113:     p(ctx, -shoulder + 2, -27, shoulder * 2 - 4, 5, shade(chestPrimary, 0.13));
114:     // tabard
115:     p(ctx, -4, -27, 8, 13, pal.cloth);
116:     p(ctx, -4, -27, 8, 2, pal.trim);
117:     p(ctx, -1, -22, 2, 8, pal.trim);
118:     // belt
119:     p(ctx, -shoulder + 1, -18, shoulder * 2 - 2, 3, '#42301f');
120:     p(ctx, -2, -18, 5, 3, pal.trim);
121:     // pauldrons
122:     p(ctx, -shoulder - 2, -30, 5, 6, pal.metal);
123:     p(ctx, -shoulder - 1, -29, 3, 2, shade(pal.metal, 0.25));
124:     p(ctx, shoulder - 3, -30, 5, 6, pal.metal);
125:     p(ctx, shoulder - 2, -29, 3, 2, shade(pal.metal, 0.25));
126:     if (demon) {
127:       p(ctx, -shoulder - 3, -31, 2, 3, '#7a2335');
128:       p(ctx, shoulder + 1, -31, 2, 3, '#7a2335');
129:     } else {
130:       p(ctx, -shoulder + 4, -29, 2, 2, pal.trim);
131:       p(ctx, shoulder - 6, -29, 2, 2, pal.trim);
132:     }
133:   } else if (o.classId === 'mage') {
134:     p(ctx, -shoulder + 1, -29, shoulder * 2 - 2, 12, chestPrimary);
135:     p(ctx, -shoulder + 3, -27, shoulder * 2 - 6, 4, shade(chestPrimary, 0.12));
136:     p(ctx, -8, -18, 16, 3, pal.trim);
137:     // robe trim
138:     p(ctx, -1, -29, 2, 11, pal.trim);
139:     p(ctx, -5, -25, 3, 3, shade(chestPrimary, 0.2));
140:     // shoulder mantle
141:     p(ctx, -shoulder, -29, 5, 4, pal.cloth2);
142:     p(ctx, shoulder - 5, -29, 5, 4, pal.cloth2);
143:     p(ctx, -shoulder, -29, 5, 1, pal.trim);
144:     p(ctx, shoulder - 5, -29, 5, 1, pal.trim);
145:   } else {
146:     p(ctx, -shoulder + 1, -29, shoulder * 2 - 2, 12, pal.cloth);
147:     p(ctx, -shoulder + 2, -27, shoulder * 2 - 4, 6, shade(chestPrimary, 0.02));
148:     p(ctx, -shoulder + 1, -29, shoulder * 2 - 2, 2, pal.cloth2);
149:     // leather straps
150:     p(ctx, -5, -28, 2, 11, pal.metal2);
151:     p(ctx, 3, -28, 2, 11, pal.metal2);
152:     p(ctx, -5, -24, 10, 2, pal.metal2);
153:     p(ctx, -shoulder + 1, -18, shoulder * 2 - 2, 3, pal.cloth2);
154:     p(ctx, -2, -18, 4, 2, pal.trim);
155:   }
156: 
157:   // necklace / chain / earrings
158:   if (eq.necklace) {
159:     p(ctx, -3, -30, 6, 1, '#d9b45a');
160:     p(ctx, -1, -29, 2, 3, EQUIP_COLOR(eq.necklace.rarity, '#d9b45a'));
161:     p(ctx, -1, -27, 1, 1, '#fff3c4');
162:   }
163:   if (eq.chain) {
164:     p(ctx, -7, -18, 14, 1, EQUIP_COLOR(eq.chain.rarity, '#c8a84f'));
165:     p(ctx, -5, -17, 1, 1, '#f5df9a');
166:     p(ctx, 3, -17, 1, 1, '#f5df9a');
167:   }
168: 
169:   // ---- head ----
170:   const headY = -43;
171:   p(ctx, -6, headY, 12, 11, skin);
172:   p(ctx, -6, headY, 12, 1, shade(skin, 0.08));
173:   p(ctx, -6, headY + 9, 12, 1, skinShade);
174:   // neck
175:   p(ctx, -2, headY + 10, 4, 3, skinShade);
176:   // eyes
177:   p(ctx, -4, headY + 5, 2, 2, '#f7f4ea');
178:   p(ctx, 2, headY + 5, 2, 2, '#f7f4ea');
179:   p(ctx, -3, headY + 5, 1, 2, o.eyeColor || '#3f8cff');
180:   p(ctx, 3, headY + 5, 1, 2, o.eyeColor || '#3f8cff');
181:   if (female) { p(ctx, -5, headY + 4, 2, 1, OUT2); p(ctx, 3, headY + 4, 2, 1, OUT2); }
182:   // mouth
183:   p(ctx, -1, headY + 9, 2, 1, shade(skin, -0.25));
184: 
185:   // horn/halo faction detail
186:   if (demon) {
187:     p(ctx, -5, headY - 3, 2, 3, '#3d1f2b');
188:     p(ctx, -6, headY - 5, 2, 3, '#5c2637');
189:     p(ctx, 3, headY - 3, 2, 3, '#3d1f2b');
190:     p(ctx, 4, headY - 5, 2, 3, '#5c2637');
191:   }
192: 
193:   // hair styles (drawn before helmet)
194:   drawHair(ctx, o.hairStyle, hair, headY, female, time);
195: 
196:   // helmet overrides hair partly
197:   if (eq.helmet) drawHelmet(ctx, o.classId, eq.helmet, headY, pal, demon);
198: 
199:   // earrings
200:   if (eq.earrings) {
201:     p(ctx, -7, headY + 6, 1, 2, EQUIP_COLOR(eq.earrings.rarity, '#ffd166'));
202:     p(ctx, 6, headY + 6, 1, 2, EQUIP_COLOR(eq.earrings.rarity, '#ffd166'));
203:   }
204: 
205:   // halo for angels — a small hollow pixel ring, not a flat bar
206:   if (!demon) {
207:     ctx.save();
208:     ctx.globalAlpha = 0.9;
209:     const hy = Math.round(headY - (eq.helmet ? 7 : 8));
210:     p(ctx, -4, hy, 8, 1, '#fff4c4');
211:     p(ctx, -5, hy + 1, 1, 1, '#ffe9a3');
212:     p(ctx, 4, hy + 1, 1, 1, '#ffe9a3');
213:     p(ctx, -4, hy + 2, 8, 1, '#e8c46a');
214:     ctx.restore();
215:   }
216: 
217:   // ---- arms + weapon ----
218:   drawArmsAndWeapon(ctx, o, pal, skin, attack, casting, time, swing);
219: 
220:   ctx.restore();
221: 
222:   // ---- aura tier (subtle, inside sprite space) ----
223:   if (o.aura) {
224:     ctx.save();
225:     ctx.globalAlpha = 0.22 + (o.aura.strength || 0) * 0.09;
226:     ctx.fillStyle = o.aura.color;
227:     ctx.beginPath();
228:     ctx.ellipse(0, -22, 14 + (o.aura.strength || 0) * 2, 24 + (o.aura.strength || 0) * 2, 0, 0, Math.PI * 2);
229:     ctx.fill();
230:     ctx.restore();
231:   }
232: 
233:   ctx.restore();
234: }
