320: function drawHelmet(ctx, classId, item, headY, pal, demon) {
321:   const rar = item.rarity;
322:   const c = EQUIP_COLOR(rar, pal.metal);
323:   const d = shade(c, -0.25);
324:   const glow = rar !== 'common' && rar !== 'grey';
325:   if (classId === 'warrior') {
326:     p(ctx, -7, headY - 3, 14, 5, d);
327:     p(ctx, -6, headY - 2, 12, 3, c);
328:     p(ctx, -6, headY + 2, 2, 3, d);
329:     p(ctx, 4, headY + 2, 2, 3, d);
330:     p(ctx, -1, headY - 1, 2, 4, shade(c, 0.2));
331:     // wings/horns on helm
332:     p(ctx, -9, headY - 2, 2, 4, c);
333:     p(ctx, 7, headY - 2, 2, 4, c);
334:     if (glow) p(ctx, -8, headY - 3, 2, 1, RARITIES[rar].color);
335:   } else if (classId === 'mage') {
336:     p(ctx, -6, headY - 2, 12, 2, c);
337:     p(ctx, -1, headY - 4, 2, 3, c);
338:     px(ctx, 0, headY - 5, RARITIES[rar].color);
339:     p(ctx, -7, headY + 1, 2, 4, d);
340:     p(ctx, 5, headY + 1, 2, 4, d);
341:   } else {
342:     // hood
343:     p(ctx, -7, headY - 3, 14, 4, shade(c, -0.1));
344:     p(ctx, -7, headY + 1, 3, 8, c);
345:     p(ctx, 4, headY + 1, 3, 8, c);
346:     p(ctx, -5, headY - 3, 2, 2, glow ? RARITIES[rar].color : '#efe6c8');
347:     p(ctx, -2, headY - 4, 4, 1, d);
348:   }
349: }
