import { createRequire } from 'node:module'
const runtime = process.env.HOME + '/.local/share/omgithub-playwright'
const require = createRequire(runtime + '/package.json')
const { chromium } = require('playwright')
const config = JSON.parse(require('node:fs').readFileSync(runtime + '/linux.json', 'utf8'))

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.setDefaultTimeout(30000)
const errors = []
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message + ' | ' + (e.stack || '').split('\n')[1]))
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()) })

const G = sel => page.evaluate(sel)
await page.goto('http://127.0.0.1:4113/', { waitUntil: 'load' })
await page.waitForTimeout(500)

// fresh save
await page.evaluate(() => localStorage.removeItem('aetheria_save_v1'))
await page.reload({ waitUntil: 'load' })
await page.waitForTimeout(600)

// create character (mage/demon for variety)
await page.click('#btnNewGame')
await page.waitForTimeout(300)
await page.fill('#createName', 'Tester')
await page.click('[data-choice="classId"][data-value="mage"]').catch(() => errors.push('no class button'))
await page.click('[data-choice="faction"][data-value="demon"]').catch(() => errors.push('no faction button'))
await page.waitForTimeout(400)
await page.click('#btnCreate')
await page.waitForTimeout(2500)
console.log('hud:', await page.locator('#hud').isVisible())

// --- real combat: teleport player next to the first living enemy via API (same as walking there) ---
await page.evaluate(() => {
  const g = window.AETHERIA.game
  const e = g.world.enemies.find(e => e.alive && !e.boss)
  g.player.x = e.x + 1.2; g.player.y = e.y + 1.2
})
await page.waitForTimeout(2500)
const afterCombat = await page.evaluate(() => {
  const s = window.AETHERIA.State
  return { gold: s.char.gold, xp: s.char.xp, kills: s.char.kills, inv: s.data.inventory.length, level: s.char.level, hp: s.char.hp }
})
console.log('after melee combat:', JSON.stringify(afterCombat))

// use the skill with an enemy nearby
await page.evaluate(() => {
  const g = window.AETHERIA.game
  const e = g.world.enemies.find(e => e.alive && !e.boss)
  g.player.x = e.x + 1.0; g.player.y = e.y + 1.0
})
await page.keyboard.press('q')
await page.waitForTimeout(1200)
console.log('mana after skill:', await page.evaluate(() => window.AETHERIA.State.char.mana))

// pick a boss fight: give tons of attack via state and test loot dropping + pickup
await page.evaluate(() => {
  const k = window.AETHERIA
  const g = k.game
  const b = g.world.enemies.find(e => e.boss)
  g.player.x = b.x + 1.5; g.player.y = b.y + 1.5
  b.hp = 1
})
await page.waitForTimeout(1800)
const afterBoss = await page.evaluate(() => {
  const g = window.AETHERIA.game
  const s = window.AETHERIA.State
  return {
    bosses: s.char.bosses, groundLoot: g.groundLoot.length, inv: s.data.inventory.length,
    invKinds: s.data.inventory.map(i => i.kind), stones: s.data.stones.length,
    gold: s.char.gold
  }
})
console.log('after boss:', JSON.stringify(afterBoss))

// --- UI-driven actions ---
// open all panels and exercise one action each
const panels = ['openBag', 'openCharacter', 'openMap', 'openShop', 'openMenu']
for (const p of panels) {
  await page.evaluate(id => window.AETHERIA.ui.handleUi(id), p)
  await page.waitForTimeout(350)
  const vis = await page.locator('#modalRoot').isVisible()
  console.log('panel', p, 'visible:', vis)
  if (!vis) errors.push('PANEL DID NOT OPEN: ' + p)
  // screenshot shop and map for review
  if (p === 'openMap') await page.screenshot({ path: '/tmp/opencode/caps/deep-map.png' })
  if (p === 'openShop') await page.screenshot({ path: '/tmp/opencode/caps/deep-shop.png' })
  await page.keyboard.press('Escape')
  await page.waitForTimeout(250)
}

// NPC panel via event
await page.evaluate(() => {
  const g = window.AETHERIA.game
  window.AETHERIA.ui.handleUi('openBag')
})
await page.waitForTimeout(300)

// buy a potion (real click path)
await page.evaluate(() => { window.AETHERIA.ui.handleUi('openMenu'); })
await page.waitForTimeout(200)
await page.evaluate(() => window.AETHERIA.State.buyPotion('health_small', 1))
console.log('potion bought:', await page.evaluate(() => window.AETHERIA.State.char.consumables.health_small))

// use potion after taking damage
await page.evaluate(() => { window.AETHERIA.State.char.hp = 10 })
await page.keyboard.press('h')
await page.waitForTimeout(300)
console.log('potion used:', await page.evaluate(() => ({ hp: window.AETHERIA.State.char.hp, left: window.AETHERIA.State.char.consumables.health_small })))

// fusion via state: create 4 identical drops
await page.evaluate(() => {
  const s = window.AETHERIA.State
  for (let i = 0; i < 4; i++) s.data.inventory.push(s.createEquip({ slot: 'helmet', rarity: 'common', tier: 3, classId: s.char.classId, faction: s.char.faction, level: 1 }))
  s.data.inventory.push(s.createEquip({ slot: 'helmet', rarity: 'common', tier: 2, classId: s.char.classId, faction: s.char.faction, level: 1 }))
})
const fuse = await page.evaluate(() => {
  const s = window.AENDERIA_State || window.AETHERIA.State
  const g = s.fusionGroups()
  if (!g.length) return { ok: false, msg: 'no groups' }
  const before = s.data.inventory.length
  const res = s.fuseGroup(g[0].key)
  return { ok: res.ok, before, after: s.data.inventory.length, msg: res.msg, created: res.item?.name, tier: res.item?.tier, rarity: res.item?.rarity }
})
console.log('fusion:', JSON.stringify(fuse))

// equip fusion result
console.log('equip:', await page.evaluate(() => {
  const s = window.AETHERIA.State
  const it = s.data.inventory.find(i => i.kind === 'equip' && i.tier === 2)
  return it ? s.equip(it.uid).msg : 'none to equip'
}))

// teleport to ironcrag + back (travel flow)
console.log('travel:', await page.evaluate(() => window.AETHERIA.game.travelTo('ironcrag')))
await page.waitForTimeout(2000)
console.log('region now:', await page.evaluate(() => window.AETHERIA.State.char.region))
console.log('travel homeργ:', JSON.stringify(await page.evaluate(() => window.AETHERIA.game.travelTo('greendale'))))
await page.waitForTimeout(1800)
console.log('region back:', await page.evaluate(() => window.AETHERIA.State.char.region))

// death flow
await page.evaluate(() => {
  const s = window.AETHERIA.State
  s.data.character.gold += 50000 // ensure teleport gold not the limiter
  window.AETHERIA.State.damagePlayer(999999)
})
await page.waitForTimeout(4500)
console.log('death/respawn:', await page.evaluate(() => ({ hp: window.AETHERIA.State.char.hp, dead: window.AETHERIA.game.player.dead, deaths: window.AETHERIA.State.char.deaths })))

// quest flow
const quest = await page.evaluate(() => {
  const s = window.AETHERIA.State
  const a = s.acceptQuest('main1')
  s.char.kills = 0
  s.onKill('slime'); s.onKill('slime')
  const prog = s.activeQuest('main1')?.progress
  return { a, prog }
})
console.log('quests:', JSON.stringify(quest))

// market + storage + skill upgrade via state
console.log('stall:', JSON.stringify(await page.evaluate(() => { window.AETHERIA.State.char.gold += 20000; return window.AETHERIA.State.rentStall().msg })))
console.log('list:', JSON.stringify(await page.evaluate(() => {
  const s = window.AETHERIA.State
  const it = s.data.inventory.find(i => i.kind === 'equip')
  return it ? s.listItem(it.uid, 1000).msg : 'no item'
})))
console.log('storage:', JSON.stringify(await page.evaluate(() => {
  const s = window.AETHERIA.State
  const it = s.data.inventory.find(i => i.kind === 'equip')
  return it ? s.depositItem(it.uid).msg : 'no item'
})))

// save + reload + continue
await page.evaluate(() => window.AETHERIA.save())
await page.reload({ waitUntil: 'load' })
await page.waitForTimeout(700)
console.log('continue visible:', await page.locator('#btnContinue').isVisible())
await page.click('#btnContinue')
await page.waitForTimeout(2200)
const finalState = await page.evaluate(() => {
  const s = window.AETHERIA.State
  return { name: s.char.name, lvl: s.char.level, gold: s.char.gold, region: s.char.region, inv: s.data.inventory.length, storage: s.data.storage.length, quests: s.data.quests, listing: s.data.market.listings.length, playtime: s.data.playtime }
})
console.log('post-reload state:', JSON.stringify(finalState))
await page.screenshot({ path: '/tmp/opencode/caps/deep-final.png' })

// mobile viewport capture for responsive check
await page.setViewportSize({ width: 390, height: 844 })
await page.waitForTimeout(vn = 900)
await page.screenshot({ path: '/tmp/opencode/caps/deep-mobile.png' })

console.log('--- ERRORS (' + errors.length + ') ---')
for (const e of errors.slice(0, 30)) console.log(e)
await browser.close()

