import { createRequire } from 'node:module'
const runtime = process.env.HOME + '/.local/share/omgithub-playwright'
const require = createRequire(runtime + '/package.json')
const { chromium } = require('playwright')
const config = JSON.parse(require('node:fs').readFileSync(runtime + '/linux.json', 'utf8'))
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.on('pageerror', e => console.log('PAGEERROR:', e.message))
await page.goto('http://127.0.0.1:4113/', { waitUntil: 'load' })
await page.waitForTimeout(400)
await page.evaluate(() => localStorage.removeItem('aetheria_save_v1'))
await page.reload({ waitUntil: 'load' })
await page.waitForTimeout(500)
await page.click('#btnNewGame'); await page.waitForTimeout(200)
await page.click('#btnCreate'); await page.waitForTimeout(2200)

const out = await page.evaluate(() => new Promise(resolve => {
  const k = window.AETHERIA
  const g = k.game
  const log = []
  k.Events.on('enemyHit', d => log.push({ t: performance.now().toFixed(0), enemy: d.enemy.type, dmg: Math.round(d.amount) }))
  k.Events.on('kill', d => log.push({ t: performance.now().toFixed(0), kill: d.enemy.type }))
  k.Events.on('toast', t => log.push({ toast: t.msg }))
  const e = g.world.enemies.find(e => e.alive && !e.boss)
  g.player.x = e.x + 1.1; g.player.y = e.y + 1.1
  setTimeout(() => resolve({
    log,
    target: g.target ? { type: g.target.type, hp: g.target.hp } : null,
    autoAttack: g.state.data.settings.autoAttack,
    attackRange: g.state.stats().attackRange,
    distance: Math.hypot(g.target.x - g.player.x, g.target.y - g.player.y),
    atkInterval: g.state.stats().attackInterval,
    attack: g.state.stats().attack,
    playerDead: g.player.dead,
    hp: g.state.char.hp
  }), 5000)
}))
console.log(JSON.stringify(out, null, 1))

// also test calling attackPressed directly
const out2 = await page.evaluate(() => new Promise(resolve => {
  const k = window.AETHERIA, g = k.game
  const e = g.world.enemies.find(e => e.alive && !e.boss)
  if (!e) return resolve('no enemy alive')
  g.player.x = e.x + 1.0; g.player.y = e.y + 1.0
  g.target = e
  e.hp = 5
  g.attackPressed()
  setTimeout(() => resolve({ enemyHp: e.hp, alive: e.alive, kills: k.State.char.kills, gold: k.State.char.gold, projectiles: g.projectiles.length }), 2500)
}))
console.log('direct attack:', JSON.stringify(out2))
await browser.close()

