const runtime = process.env.HOME + '/.local/share/omgithub-playwright'
const require = createRequire(runtime + '/package.json')
const { chromium } = require('playwright')
const config = JSON.parse(require('node:fs').readFileSync(runtime + '/linux.json', 'utf8'))
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 390, height: 844 } })
page.on('pageerror', e => console.log('PAGEERROR:', e.message))
await page.goto('http://127.0.0.1:4113/', { waitUntil: 'load' })
await page.waitForTimeout(400)
await page.evaluate(() => localStorage.removeItem('aetheria_save_v1'))
await page.reload({ waitUntil: 'load' })
await page.waitForTimeout(500)
await page.click('#btnNewGame'); await page.waitForTimeout(200)
await page.click('#btnCreate'); await page.waitForTimeout(2200)

// real death via a boss hit path
const death = await page.evaluate(() => new Promise(resolve => {
  const k = window.AETHERIA, g = k.game
  g.playerDie()
  setTimeout(() => resolve({
    overlayShown: !document.getElementById('deathOverlay').classList.contains('hidden'),
    deaths: k.State.char.deaths
  }), 800)
}))
console.log('death:', JSON.stringify(death))

const respawn = await page.evaluate(() => new Promise(resolve => {
  const k = window.AETHERIA
  setTimeout(() => resolve({
    dead: false,
    hp: k.State.char.hp,
    hpMax: k.State.stats().maxHp,
    region: k.State.char.region,
    overlayHidden: document.getElementById('deathOverlay').classList.contains('hidden')
  }), 4200)
}))
console.log('respawn:', JSON.stringify(respawn))

// travel for real now (with gold)
console.log('travel:', await page.evaluate(() => { window.AETHERIA.State.char.gold += 50000; return window.AETHERIA.game.travelTo('venomwood') }))
await page.waitForTimeout(2000)
console.log('region:', await page.evaluate(() => window.AETHERIA.State.char.region))
console.log('toast:', await page.evaluate(() => document.getElementById('toastHost').lastElementChild?.textContent))
console.log('hud region chip:', await page.evaluate(() => document.getElementById('hudRegion').textContent))
await page.waitForTimeout(1200)
await page.screenshot({ path: '/tmp/opencode/caps/venomwood.png' })

// enchanter flow: boss kill gives stone -> apply via state
const enc = await page.evaluate(() => {
  const s = window.AETHERIA.State
  s.addStone({ uid: 'test_st1', kind: 'stone', classId: s.char.classId, stat: 'crit', value: 2.5, tier: 2, name: 'Greater Critical Stone', icon: '✹', desc: 'x' })
  const item = s.data.inventory.find(i => i.kind === 'equip')
  s.char.gold += 50000
  const res = s.applyStone(item.uid, 'test_st1', -1)
  return { msg: res.msg, bonuses: item.bonuses, crit: s.stats().crit, critStat: s.stats().critBonus }
})
console.log('enchant:', JSON.stringify(enc))

// critical cap check: stack crit stones
const cap = await page.evaluate(() => {
  const s = window.AETHERIA.State
  const item = s.data.inventory.find(i => i.kind === 'equip')
  item.stats.crit = 0.4
