943:   drawMinimap(canvas, game) {
944:     const ctx = canvas.getContext('2d');
945:     const world = this.world;
946:     const w = canvas.width, h = canvas.height;
947:     ctx.clearRect(0, 0, w, h);
948:     ctx.fillStyle = 'rgba(8,7,14,0.88)';
949:     ctx.fillRect(0, 0, w, h);
950:     if (!world) return;
951:     const pad = 4;
952:     const scale = Math.min((w - pad * 2) / world.size, (h - pad * 2) / world.size);
953:     const ox = (w - world.size * scale) / 2;
954:     const oy = (h - world.size * scale) / 2;
955:     for (let y = 0; y < world.size; y++) {
956:       for (let x = 0; x < world.size; x++) {
957:         const t = world.tiles[y * world.size + x];
958:         let col = '#2b3d2e';
959:         if (t.type === 'water') col = '#25505c';
960:         else if (t.type === 'path' || t.type === 'plaza') col = '#6b5a3d';
961:         else if (t.type === 'void') col = '#0a0918';
962:         else if (t.type === 'ground2') col = shade(world.region.palette.ground2, -0.1);
963:         else if (t.type === 'ground3') col = shade(world.region.palette.ground3, -0.1);
964:         ctx.fillStyle = col;
965:         ctx.fillRect(ox + x * scale, oy + y * scale, Math.ceil(scale), Math.ceil(scale));
966:       }
967:     }
968:     // npcs
969:     for (const n of world.npcs) {
970:       ctx.fillStyle = '#ffd166';
971:       ctx.fillRect(ox + n.x * scale - 1, oy + n.y * scale - 1, 3, 3);
972:     }
973:     // enemies
974:     for (const e of world.enemies) {
975:       if (!e.alive) continue;
976:       ctx.fillStyle = e.boss ? '#ff4d4d' : e.elite ? '#ffd166' : 'rgba(255,110,110,0.75)';
977:       const sz = e.boss ? 4 : 2;
978:       ctx.fillRect(ox + e.x * scale - sz / 2, oy + e.y * scale - sz / 2, sz, sz);
979:     }
980:     // player
981:     const px = ox + game.player.x * scale;
982:     const py = oy + game.player.y * scale;
983:     ctx.fillStyle = '#fff3c4';
984:     ctx.beginPath(); ctx.arc(px, py, 3, 0, Math.PI * 2); ctx.fill();
985:     ctx.strokeStyle = '#1a1520'; ctx.lineWidth = 1; ctx.stroke();
986:     // border + region label
987:     ctx.strokeStyle = 'rgba(230,196,106,0.35)';
988:     ctx.strokeRect(0.5, 0.5, w - 1, h - 1);
989:   }
990: }
