// ------------------------------------------------------------
// RUNNING DUST
// ------------------------------------------------------------
spawnDust(game) {
  if (!game.player.moving || !game.state) return;
  this._dustCd = (this._dustCd || 0) - this._dt || 0;
  this._dt = this._dt || 0;
  this._dustAcc = (this._dustAcc || 0) + this._dt;
  if (this._dustAcc < 0.14) return;
  this._dustAcc = 0;
  const p = this.iso(game.player.x, game.player.y);
  this.dust.push({
    x: p.x - this.cam.x + (Math.random() - 0.5) * 8,
    y: p.y - this.cam.y + 2,
    vx: (Math.random() - 0.5) * 14,
    vy: -6 - Math.random() * 8,
    life: 0.55 + Math.random() * 0.3,
    maxLife: 0.85,
    size: 2 + Math.random() * 2
  });
  this._dt = 0;
}

updateDust(dt) {
  this._dt = dt;
  for (const d of this.dust) {
    d.life -= dt;
    d.x += d.vx * dt;
    d.y += d.vy * dt;
    d.vy += 20 * dt;
  }
  this.dust = this.dust.filter(d => d.life > 0);
}

drawDust(ctx) {
  const pal = this.world.region.palette;
  const base = shade(pal.ground1, 0.22);
  for (const d of this.dust) {
    const a = clamp(d.life / d.maxLife, 0, 1) * 0.3;
    ctx.globalAlpha = a;
    ctx.fillStyle = base;
    const s = d.size * (1 + (1 - d.life / d.maxLife));
    ctx.fillRect(d.x - s / 2, d.y - s / 2, s, s * 0.8);
  }
  ctx.globalAlpha = 1;
}

