      ctx.fillRect(cx + dx, cy + dy - 2, 1, 3);
      ctx.fillRect(cx + dx + 2, cy + dy - 1, 1, 2);
      ctx.fillStyle = shade(base, -0.13);
      ctx.fillRect(cx + dx - 2, cy + dy, 1, 2);
