import { createRequire } from 'node:module'
const runtime = process.env.HOME + '/.local/share/omgithub-playwright'
const require = createRequire(runtime + '/package.json')
const { chromium } = require('playwright')
const fs = require('node:fs')
const config = JSON.parse(fs.readFileSync(runtime + '/linux.json', 'utf8'))
const errors = []
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 860 } })
page.on('pageerror', e => errors.push(e.message))
await page.goto('http://127.0.0.1:4113/', { waitUntil: 'load' })
await page.waitForTimeout(400)
await page.evaluate(() => localStorage.removeItem('aetheria_save_v1'))
await page.reload({ waitUntil: 'load' })
await page.waitForTimeout(400)
await page.click('#btnNewGame'); await page.waitForTimeout(250)
await page.click('#btnCreate'); await page.waitForTimeout(2400)

for (const r of ['venomwood', 'ironcrag', 'sunscorch', 'tower']) {
  await page.evaluate(rid => { window.AETHERIA.State.char.gold += 300000; return window.AETHERIA.game.travelTo(rid) }, r)
  await page.waitForTimeout(2600)
  await page.screenshot({ path: `/tmp/opencode/caps/g-${r}.png` })
}

// combat kill test: pick nearest enemy, stand until dead
const combat = await page.evaluate(() => new Promise(resolve => {
  const g = window.AETHERIA.game
  let best = null, bd = Infinity
  for (const e of g.world.enemies) { if (!e.alive) continue; const d = Math.hypot(e.x - g.player.x, e.y - g.player.y); if (d < bd) { bd = d; best = e } }
  if (!best || bd > 7) { resolve({ skipped: true }); return }
  g.target = best
  g.input.moveTarget = { x: best.x + 0.6, y: best.y + 0.6 }
  setTimeout(() => {
    const killed = !best.alive || best.hp < best.maxHp
    const loots = (g.groundLoot || []).length
    resolve({ killed, lootDrops: loots, targetName: best.def.name, hp: best.hp, maxHp: best.maxHp })
  }, 9000)
}))
console.log('combat:', JSON.stringify(combat))
if ((await page.evaluate(() => (window.AETHERIA.game.groundLoot || []).length > 0))) {
  await page.evaluate(() => {
    const g = window.AETHERIA.game
    const l = g.groundLoot[0]
    g.player.x = l.x + 0.3; g.player.y = l.y + 0.3
  })
  await page.waitForTimeout(700)
  const picks = await page.evaluate(() => (window.AETHERIA.game.groundLoot || []).length)
  console.log('loot pickup attempt; groundLoot left:', picks)
}
console.log('stock of new graphics errors:', 'check ERRORS line')
console.log('ERRORS:', errors.length ? errors : 'NONE')
await browser.close()

